/**
 * 【Mạng lười dâm khiếu】Thiết bị đầu cuối hàng hóa tùy chỉnh X Dạng Siêu Việt
 * Thông báo workshop có thể thu gọn / Loại khóa tạo vật+Bể từ khóa siêu lớn / Thẻ nhân cách Nhành Vàng TYPE-θ Tái cấu trúc / Ngục Gương CRT Máy quay thẻ(Tích hợp trong cửa sổ nổi)
 */
(() => {
  try {
  const ROOT_ID='th-yinjiao-network-terminal';
  const POS_KEY='th-yinjiao-pos-v10',API_KEY='th-yinjiao-api-v10',UI_KEY='th-yinjiao-ui-v10';
  const FAV_KEY='th-yinjiao-fav-v10',CAT_KEY='th-yinjiao-cat-v11',SUB_KEY='th-yinjiao-submodes-v20';
  const NOTICE_KEY='th-yinjiao-notice-open-sv',CHAT_VAR_KEY='yj_v21_state',LS_PREFIX='yj_v21_';
  const WB_STORE_KEY='yj_v21_wb_items',BOOK_KEYWORDS=['Mạng lười dâm khiếu','Mạng Lưới Rên Dâm','淫叫网络','115901c5a2e2973f'],U='{{user}}',WB_TYPE='wbitems';
  const P=(()=>{try{const c=window.parent;return c&&c.document?c:window}catch(_){return window}})();
  const D=P.document;
  // Dấu hiệu khởi động: script chạy đến đây sẽ làm sáng một chấm xanh lá ở góc dưới bên phải trang, biến mất sau 5 giây
  try{
    const mk=D.createElement('div');
    mk.id='yj-boot-mark';
    mk.style.cssText='position:fixed;right:8px;bottom:8px;width:10px;height:10px;border-radius:50%;background:#22c55e;box-shadow:0 0 10px #22c55e;z-index:2147483647;pointer-events:none;font:10px/1 monospace';
    (D.body||D.documentElement).appendChild(mk);
    setTimeout(()=>{try{mk.remove()}catch(_){}},6000);
  }catch(_){}
  const STAGE=(()=>{
    try{
      const d=D.createElement('div');
      d.id='yj-stage';
      d.style.cssText='position:fixed;right:8px;bottom:26px;z-index:2147483647;background:#0b0b0b;color:#7CFC00;font:11px/1.4 ui-monospace,monospace;padding:4px 8px;border-radius:4px;pointer-events:none;opacity:.9;letter-spacing:.5px';
      d.textContent='Giai đoạn 0 · Khởi động';
      (D.body||D.documentElement).appendChild(d);
      return {
        set(t){try{d.textContent=t}catch(_){}},
        fail(t){try{d.textContent=t;d.style.background='#7f1d1d';d.style.color='#fff'}catch(_){}},
        done(){try{d.remove()}catch(_){}}
      };
    }catch(_){return {set(){},fail(){},done(){}}}
  })();
  const FRAME=(()=>{try{return window.frameElement||null}catch(_){return null}})();
  try{P.__TH_YINJIAO_CLEANUP__&&P.__TH_YINJIAO_CLEANUP__()}catch(_){}
  const AC=new AbortController();
  D.getElementById(ROOT_ID)?.remove();

  /* ===== Phân loại ===== */
  const CATS=[
    {id:'all',name:'Tất cả đạo cụ',codes:[]},
    {id:'fav',name:'★ Danh sách thường dùng',codes:[]},
    {id:'cat_1',name:'Thôi miên ý thức và thao túng cơ thể',codes:['001','009','011','063','065','071','080','083','088','089','090','096','103','104','124','143']},
    {id:'cat_2',name:'Tẩy não nhân cách và xuyên tạc ký ức',codes:['007','038','040','045','046','075','081','085','091','095','097','107','112','119','128','131','138','139','144','146']},
    {id:'cat_3',name:'Luật nhân quả và viết lại tầng trên của tự sự',codes:['006','015','023','028','030','047','053','056','060','069','072','100','106','108','110','120','125','126','127','140','142','145','150']},
    {id:'cat_4',name:'Tàng hình và dòm ngó giác quan',codes:['002','003','004','012','025','026','044','059','066','077','079','105','151']},
    {id:'cat_5',name:'Biến dạng cơ thể và dị cấu nội tạng',codes:['008','010','016','017','029','035','039','041','043','051','057','062','064','074','082','087','102','109','111','113','114','115','117','122','132','134','135','148','149','152']},
    {id:'cat_6',name:'Sinh lý độc lý và lệ thuộc khoái cảm',codes:['005','018','034','037','042','052','054','055','068','070','086','092','093','094','098','116','123','136','141']},
    {id:'cat_7',name:'Trói buộc vật lý và cơ khí hạng nặng',codes:['020','022','027','031','032','048','049','067','084','118']},
    {id:'cat_8',name:'Can thiệp thời không và lãnh vực dị độ',codes:['013','014','019','021','024','033','036','050','058','061','073','076','078','099','101','121','129','130','133','137','147']},
    {id:'lore',name:'◈ Thế giới quan và tổng quan',codes:[]}
  ];
  const CAT_NAMES=CATS.filter(c=>c.id!=='all'&&c.id!=='fav'&&c.id!=='lore').map(c=>c.name);
  const C2CAT=new Map();CATS.forEach(c=>c.codes.forEach(k=>C2CAT.set(k,c.id)));
  const EDIT_CATS=CATS.filter(c=>c.id!=='all'&&c.id!=='fav');
  const catIdByName=n=>{const h=EDIT_CATS.find(c=>c.name===n);return h?h.id:''};
  const CAT_HINT=[['cat_1',['Thôi miên','Thao túng ý thức','Con rối','Chỉnh sửa nhận thức','Thao túng cơ thể']],['cat_2',['Tẩy não','Xáo trộn ký ức','Nhân cách','Ràng buộc','Luân lý']],['cat_3',['Luật nhân quả','Tự sự','Viết lại quy tắc','Khế ước','Viết lại xác suất']],['cat_4',['Ẩn tung','Tàng hình','Thâm nhập','Nhìn lén','Trong suốt']],['cat_5',['Biến dạng','Cơ quan','Cải tạo','Biến hình','Ký sinh','Dị hóa']],['cat_6',['Độc lý','Khoái cảm','Dịch cơ thể','Dược lý','Sinh lý','Gây nghiện','Thôi tình']],['cat_7',['Trói buộc','Trọng trang','Cơ khí','Kiềm tỏa','Trói dây','Hình cụ','Trói dây leo']],['cat_8',['Thời không','Lãnh vực','Dị độ','Không gian','Thời gian','Dịch chuyển','Mộng cảnh']]];
  const CAT_DESC={cat_1:['Thôi miên ý thức và thao túng cơ thể','Tước đoạt hoặc làm suy yếu ý thức tự chủ và khả năng hành động của mục tiêu, cưỡng ép tiếp quản quyền kiểm soát thể xác hoặc biến thành con rối phục tùng。'],cat_2:['Tẩy não nhân cách và xuyên tạc ký ức','Đi sâu vào tầng đáy tâm trí, tái cấu trúc đặc điểm nhân cách, hồi tưởng ký ức, giới hạn đạo đức và ràng buộc tình cảm。'],cat_3:['Luật nhân quả và viết lại tầng trên của tự sự','Từ chiều không gian khái niệm bẻ cong nhân quả thực tại, biên soạn kịch bản, lập khế ước tuyệt đối hoặc viết lại thuần phong mỹ tục。'],cat_4:['Tàng hình và dòm ngó giác quan','Ẩn nấp trong thực tại hoặc điểm mù nhận thức, hoặc đọc, chiếu rọi, chia sẻ dữ liệu thân tâm của mục tiêu từ xa。'],cat_5:['Biến dạng cơ thể và dị cấu nội tạng','Thay đổi hình thái vật lý, tỷ lệ cơ thể, thêm bớt cơ quan sinh dục và đặc điểm viễn tưởng, hoặc ký sinh thần kinh não。'],cat_6:['Sinh lý độc lý và lệ thuộc khoái cảm','Tiếp quản hệ nội tiết, chất dẫn truyền thần kinh quá tải, thể dịch gây nghiện hoặc đảo ngược cảm giác đau đớn và xấu hổ thành khoái lạc tột cùng。'],cat_7:['Trói buộc vật lý và cơ khí hạng nặng','Dùng chất liệu cố hóa, dây leo sống, bộ khung xương ngoài để cố định tư thế tuyệt đối và huấn luyện cơ khí hóa。'],cat_8:['Can thiệp thời không và lãnh vực dị độ','Thao túng tốc độ thời gian, xuyên qua mặt gương và giấc mơ, hoặc kiến tạo lĩnh vực mật thất mang quy luật độc lập。']};

  let CATOV={};try{const v=JSON.parse(localStorage.getItem(CAT_KEY)||'{}');if(v&&typeof v==='object')CATOV=v}catch(_){}
  const saveCatOv=()=>{try{localStorage.setItem(CAT_KEY,JSON.stringify(CATOV))}catch(_){}};
  let SUBOV={};try{const v=JSON.parse(localStorage.getItem(SUB_KEY)||'{}');if(v&&typeof v==='object')SUBOV=v}catch(_){}
  const saveSubOv=()=>{try{localStorage.setItem(SUB_KEY,JSON.stringify(SUBOV))}catch(_){}};
  const catFromText=t=>{t=String(t||'');if(!t)return '';for(const r of CAT_HINT)for(const k of r[1])if(t.indexOf(k)>=0)return r[0];return ''};

  /* ===== Loại hồ sơ ===== */
  const PERSONA_FIELDS=[['name','Tên thẻ（Tên·Tổ chức·Chức vụ）'],['rarity','Số đèn（1~3）'],['concept','Khái niệm nhân cách（Định ngữ+Thân phận）'],['bi_id','Thông tin cơ bản·Thân phận'],['bi_look','Thông tin cơ bản·Ngoại hình'],['bi_skill','Thông tin cơ bản·Năng lực'],['bi_rel','Thông tin cơ bản·Quan hệ'],['bi_other','Thông tin cơ bản·Khác'],['na_self','Tường thuật nhân cách·Tự nhận thức（Ngôi thứ nhất“Tôi”）'],['na_need','Tường thuật nhân cách·Nhu cầu cốt lõi'],['na_goal','Tường thuật nhân cách·Mục tiêu hiện tại'],['na_arc','Tường thuật nhân cách·Cung quá khứ'],['na_trait','Tường thuật nhân cách·Đặc điểm tiến hóa'],['na_future','Tường thuật nhân cách·Xu hướng tương lai'],['history','Lịch sử song song（Mỗi dòng một mục: 5 khoảng thời gian dài+2 Bản chụp nhanh）']];
  const TYPES={
    personas:{scopes:['target'],label:'Thẻ nhân cách đồng vị Kim Chi',icon:'🎴',fields:PERSONA_FIELDS},
    brands:{scopes:['target'],label:'Dâm văn tùy chỉnh',icon:'⛧',fields:[['name','Tên dâm văn'],['look','Ngoại hình dâm văn'],['effect','Hiệu ứng dâm văn']]},
    genes:{scopes:['target'],label:'Gen di truyền',icon:'🧬',fields:[['name','Tên gen'],['look','Thuộc tính gen'],['effect','Hiệu ứng gen']]},
    cards:{scopes:['target'],label:'Thẻ bài Thư viện',icon:'📚',fields:[['name','Tên thẻ bài'],['look','Phẩm chất thẻ bài'],['effect','Hiệu ứng thẻ bài']]},
    idols:{scopes:['target'],label:'Tượng thần R’lyeh',icon:'🗿',fields:[['name','Tên giáo điều'],['look','Tín đồ / Mục tiêu'],['terms','Nội dung giáo điều'],['effect','Phản ứng cai nghiện và hậu quả vi phạm']]},
    chains:{scopes:['target'],label:'Khóa của người khác',icon:'⛓',fields:[['name','Nhãn vật hóa'],['look','Mục tiêu bị vật hóa'],['terms','Phạm vi và tình huống sử dụng'],['effect','Hành vi vô thức của người qua đường']]},
    wombs:{scopes:['target'],label:'Que thử thai nhanh',icon:'🥚',fields:[['name','Thiết lập thụ thai'],['look','Mục tiêu'],['terms','Thiết lập con cái'],['effect','Trạng thái mang thai']]},
    traps:{scopes:['target'],label:'Hạt giống cạm bẫy',icon:'🌱',fields:[['name','Hình dạng cạm bẫy'],['look','Khu vực bố trí'],['terms','Địa hình sống và trói buộc'],['effect','Kích hoạt và giải trừ']]},
    tags:{scopes:['target'],label:'Nhãn danh tính',icon:'🏷',fields:[['name','Nhãn danh tính'],['look','Người bị gắn nhãn'],['terms','Viết lại nhận thức xung quanh'],['effect','Đồng bộ pháp luật và môi trường']]},
    charms:{scopes:['target'],label:'Dâm chế phù chú',icon:'🧿',fields:[['name','Tên phù chú'],['look','Quy tắc viết'],['terms','Vị trí dán và điều kiện'],['effect','Hiệu ứng cưỡng ép và hình phạt']]},
    crystals:{scopes:['target'],label:'Kết tinh Nguyên Thạch',icon:'💠',fields:[['name','Tên kết tinh'],['look','Chế độ ký ức'],['terms','Đặc điểm hóa thân ma vật nương'],['effect','Hiệu ứng cải tạo thân tâm']]},
    parasites:{scopes:['target'],label:'Ký sinh dị sinh thú',icon:'🦠',fields:[['name','Tên vật Ký sinh'],['look','Giai đoạn ký sinh'],['terms','Thông số cơ quan sinh dục phụ'],['effect','Khoái cảm kép và cách gỡ']]},
    orders:{scopes:['target'],label:'Chỉ lệnh triệu hồi',icon:'📟',fields:[['name','Tên chỉ lệnh'],['look','Nội dung chỉ lệnh'],['terms','Lộ trình trừng phạt chống đối'],['effect','Thưởng phạt sau khi phục tùng']]},
    slimes:{scopes:['target'],label:'Cải tạo Slime',icon:'🌀',fields:[['name','Tên cải tạo'],['look','Bộ phận cải tạo'],['terms','Thêm bớt cơ quan'],['effect','Hiệu ứng sau Cải tạo']]},
    binds:{scopes:['target'],label:'Hình cụ cơ khí',icon:'🦾',fields:[['name','Tên hình cụ'],['look','Hình dáng khí giới và cách đeo'],['terms','Cấu trúc cố định / Cổng kết nối chi giả'],['effect','Hiệu ứng trói buộc và huấn luyện']]},
    vines:{scopes:['target'],label:'Nghệ thuật trói dây leo',icon:'🌹',fields:[['name','Tên kiểu trói hoa'],['look','Chất liệu dây leo và tư thế trói buộc'],['terms','Đường quấn và gai tê liệt'],['effect','Cảm giác trói buộc và cách gỡ']]},
    dishes:{scopes:['target'],label:'Hiệu quả món ăn',icon:'🍲',fields:[['name','Tên món ăn'],['look','Nguyên liệu và công dụng'],['effect','Thời gian duy trì và tác dụng phụ']]},
    swaps:{scopes:['target'],label:'Trao đổi đồng giá',icon:'⚖',fields:[['name','Tên trao đổi'],['look','Cảm xúc bị thay thế / Cái giá'],['effect','Hiệu ứng sau chuyển hóa']]},
    residues:{scopes:['target'],label:'Ấn ký tàn dư',icon:'🩸',fields:[['name','Tên tàn dư'],['look','Tính dục bị tước đoạt'],['effect','Hiệu ứng chuyển dịch và hấp thụ']]},
    skills:{scopes:['target','user'],label:'Chip kỹ năng',icon:'🔌',fields:[['name','Tên kỹ năng'],['look','Cấp độ / Độ thông thạo'],['effect','Hiệu quả kỹ năng']]},
    buffs:{scopes:['user'],label:'Cố định sinh mệnh',icon:'♾',fields:[['name','Tên cơ chế'],['effect','Hiệu quả cơ chế'],['note','Điều kiện kích hoạt và ghi chú']]},
    pacts:{scopes:['user'],label:'Khế ước điều kiện',icon:'📜',fields:[['name','Tên khế ước'],['look','Đối tượng ký kết và điều khoản'],['effect','Tiền phạt vi phạm và thi hành']]},
    bag:{scopes:['user'],label:'Tạo vật vali',icon:'🧰',fields:[['name','Tên tạo vật'],['look','Thông số chế tạo / Số lượng'],['effect','Mô tả công dụng']]},
    forms:{scopes:['user'],label:'Hình thái trái ác quỷ',icon:'🍎',fields:[['name','Tên hình thái'],['effect','Hiệu ứng hình thái'],['note','Điều kiện chuyển đổi']]},
    templates:{scopes:['user'],label:'Mẫu thiết bị ghi chép',icon:'🧾',fields:[['name','Tên mẫu'],['look','Thiết lập hình thái'],['effect','Hiệu ứng mẫu']]},
    beasts:    { scopes:['target'], label:'Tạo vật quái thú hóa', icon:'🐉', fields:[['name','Tên tạo vật'],['look','Đối tượng bị quái vật hóa'],['terms','Hình dạng và cấu tạo quái vật'],['effect','Cách xâm phạm và cách gỡ']] },
    swarms:    { scopes:['target'], label:'Huấn luyện bầy trùng', icon:'🐛', fields:[['name','Tên bầy trùng'],['look','Mục tiêu và địa điểm'],['terms','Thuộc tính và số lượng bầy côn trùng'],['effect','Hiệu ứng huấn luyện và cách gỡ']] },
    crowns:    { scopes:['target'], label:'Huyền Băng Quang Chủng', icon:'❄', fields:[['cat','Nhánh（Thần bị / Vặn vẹo）'],['name','Đối tượng cụ thể hóa'],['concept','Khái niệm hình thái'],['look','Tâm ma hoặc đối tượng ràng buộc'],['terms','Hình thái và năng lực'],['voice','Tự thuật'],['effect','Ảnh hưởng thân tâm và cách gỡ']] },
    wbitems:{scopes:['lib'],label:'Vật phẩm mới',icon:'📕',fields:[['code','Số thứ tự đạo cụ'],['name','Tên đạo cụ'],['cat','Thuộc tám nhóm phân loại'],['keys','Từ khóa kích hoạt'],['strategy','Chiến lược kích hoạt'],['order','Trọng số thứ tự'],['subs','Chế độ con'],['desc','Thông tin cơ bản'],['mech','Cơ chế và cách dùng'],['core','Hiệu ứng cốt lõi'],['scene','Bối cảnh nhập vai'],['safe','Ghi đè an toàn']]}
  };
  const T_ORDER=['crowns','beasts','swarms','personas','brands','genes','cards','idols','chains','wombs','traps','tags','charms','crystals','parasites','orders','slimes','binds','vines','dishes','swaps','residues','skills'];
  const U_ORDER=['buffs','pacts','bag','skills','forms','templates'];
  const CORE=[];T_ORDER.concat(U_ORDER).forEach(t=>{if(CORE.indexOf(t)<0)CORE.push(t)});
  const ALL=CORE.concat([WB_TYPE]);
  const WST=CORE.slice();
  const LOCKED=['cat','keys','subs','strategy','order'];

  /* ===== Bể ngẫu nhiên đa chiều thế giới gương ===== */
  const MR=[
    '【Paypig】Đạt được khoái cảm thông qua việc nộp tiền cho kẻ thống trị và chấp nhận bị sỉ nhục về tài chính',
    '【Brat】Kiểu tinh nghịch cố tình khiêu khích chống đối để đổi lấy kỷ luật và trừng phạt',
    '【Submissive Masochist】Trực tiếp lấy khoái cảm tình dục từ đau đớn thể xác và tra tấn',
    '【Service Sub】Đạt được sự thỏa mãn sâu sắc thông qua hoàn thành nhiệm vụ, phục vụ và phục tùng',
    '【Puppy】Trong nhập vai thú cưng, bị huấn luyện, dắt dẫy và khống chế như chó',
    '【Little】Trong đóng vai tuổi tác, thoái lui về trạng thái ấu trĩ và tìm kiếm sự chăm sóc hướng dẫn',
    '【Slave】Hoàn toàn từ bỏ quyền tự chủ, chấp nhận quyền sở hữu toàn diện và khống chế lâu dài',
    '【Rope Bunny】Lấy việc bị trói bằng dây thừng, treo lơ lửng và hạn chế làm khoái cảm cốt lõi',
    '【Humiliation Sub】Đạt được khoái cảm từ việc hạ thấp bằng lời nói, sỉ nhục công khai và đàn áp tâm lý',
    '【Object Sub】Hưởng thụ việc bị vật hóa thành đồ nội thất hoặc vật vô tri',
