  (function buildStar(){
    const p=root.querySelector('.sp-star');
    if(!p)return;
    const N=12,R=49,r=19,cx=50,cy=50,pts=[];
    for(let i=0;i<N*2;i++){
      const rad=(i%2===0)?R:r;
      const a=(Math.PI/N)*i-Math.PI/2;
      pts.push((cx+rad*Math.cos(a)).toFixed(2)+','+(cy+rad*Math.sin(a)).toFixed(2));
    }
    p.setAttribute('d','M'+pts.join(' L')+' Z');
  })();

