  function normLib(raw){
    if(!raw||typeof raw!=='object')return null;
    const out=emptyLib();
    Object.keys(raw).forEach(t=>{
      if(!TYPES[t]||t===WB_TYPE)return;
      const def=TYPES[t];
      (raw[t]||[]).forEach(rec=>{
        if(!rec)return;
        const o={id:rec.id||uid()};
        def.fields.forEach(f=>o[f[0]]=String(rec[f[0]]==null?'':rec[f[0]]));
        out[t].push(o);
      });
    });
    return out;
  }
