  /* ===== Phân tích Sách thế giới ===== */
  const SECS=[['Thông tin cơ bản','Thông tin cơ bản','◈'],['Cơ chế & Cách dùng','Cơ chế & Cách dùng','⚙'],['Hiệu ứng cốt lõi','Hiệu ứng cốt lõi','✦'],['Bối cảnh nhập vai','Bối cảnh nhập vai','🎭'],['Ghi đè an toàn','Ghi đè an toàn','🛡']];
  const SEC_ALIAS=[['Thông tin cơ bản',['Thông tin cơ bản']],['Cơ chế & Cách dùng',['Cơ chế & Cách dùng','Cơ chế và cách dùng','Cơ chế và cách sử dụng']],['Hiệu ứng cốt lõi',['Hiệu ứng cốt lõi','Hiệu quả cốt lõi']],['Bối cảnh nhập vai',['Bối cảnh nhập vai','Kịch bản nhập vai','Tình huống nhập vai']],['Ghi đè an toàn',['Ghi đè an toàn','Bảo hiểm an toàn','Bảo vệ an toàn','Bảo đảm an toàn','Đảm bảo an toàn','Cơ chế an toàn','Phạm vi an toàn','Phủ sóng an toàn','Cơ chế bảo toàn an toàn','Phạm vi bảo mật','An toàn ghi đè','Bảo hộ an toàn','Cơ chế bảo vệ an toàn']]];
  const SEC_RE=new RegExp('^('+SEC_ALIAS.map(a=>a[1].join('|')).join('|')+')[ \\t]*[:：][ \\t]*(.*)$','i');
  const secKey=h=>{const x=String(h).toLowerCase();const f=SEC_ALIAS.find(a=>a[1].some(n=>n.toLowerCase()===x));return f?f[0]:h};
  function parseEntry(e){
    const raw=String(e.content||''),cm=String(e.name||e.comment||'').trim();
    let code='',title=cm;
    const m1=cm.match(/^([0-9]{3})[ \t]*[.、:：]?[ \t]*(.+)$/);
    if(m1){code=m1[1];title=m1[2].trim().replace(/^\[[ \t]*['"]?/,'').replace(/['"]?[ \t]*\]/,'').trim()}else{const mc=raw.match(/^Mã số[ \t]*[:：][ \t]*['"]?([0-9]{1,4})['"]?/m);const mn=raw.match(/^Tên(?: gọi)?[ \t]*[:：][ \t]*(.+)$/m);if(mc)code=mc[1].padStart(3,'0');if(mn)title=mn[1].trim()}
    const isLore=!code&&(cm.indexOf('Thế giới quan')>=0||cm.indexOf('Mục lục')>=0||cm.indexOf('Danh mục')>=0||cm.indexOf('Phân loại')>=0);
    const buf={};SECS.forEach(s=>buf[s[0]]=[]);
    let cur=null;
    raw.split('\n').forEach(ln=>{
      const t=ln.match(SEC_RE);
      if(t){cur=secKey(t[1]);if(t[2].trim())buf[cur].push(t[2].trim());return}
      if(/^(Mã số|Tên gọi|Tên vật phẩm|Tên|Giải thích tên gọi|Giải thích tên|Mô tả tên gọi|Mô tả tên)[ \t]*[:：]/i.test(ln)){cur=null;return}
      if(cur)buf[cur].push(ln);
    });
    const sections={};SECS.forEach(s=>sections[s[0]]=buf[s[0]].join('\n').trim());
    const base=sections['Thông tin cơ bản']||raw;
    const cm2=base.match(/(?:^|\n)[ \t\-*]*(?:Phân loại|Loại)[ \t]*[:：][ \t]*([^\r\n]+)/i);
    const tagTxt=cm2?cm2[1]:'';
    const tags=tagTxt?tagTxt.replace(/[。.]$/,'').split(/[、，,]/).map(s=>s.trim()).filter(Boolean):((e.strategy&&e.strategy.keys)||[]);
    let subs=[];
    (sections['Cơ chế & Cách dùng']||'').split('\n').forEach(ln=>{
      const m=ln.match(/^[ \t]*-[ \t]*\*{0,2}([^:：\n]{2,18}?)\*{0,2}[ \t]*[:：]/);
      if(!m||subs.length>=12)return;
      const c=m[1].replace(/\*+/g,'').trim();
      if(c&&['Cách dùng khiêu dâm','Cách gỡ bỏ','Thời gian hiệu lực','Cách thu hồi','Cách sử dụng'].indexOf(c)<0&&subs.indexOf(c)<0)subs.push(c);
    });
    if(code&&SUBOV[code]&&Array.isArray(SUBOV[code]))subs=SUBOV[code].slice(0,12);
    const catId=isLore?'lore':(CATOV[code]||C2CAT.get(code)||catFromText(tagTxt)||catFromText(raw)||'cat_1');
    const cd=CATS.find(c=>c.id===catId)||CATS[0];
    return {uid:e.uid,entry:e,code,title:title||('Chưa đặt tên #'+e.uid),isLore,categoryId:catId,categoryName:cd.name,tags,submodes:subs,sections,raw};
  }
  function buildYaml(code,name,vals){
    const c=String(code||'').trim().padStart(3,'0'),n=String(name||'Đạo cụ chưa đặt tên').trim();
    const out=["Mã số: '"+c+"'",'Tên: '+n,'Giải thích tên:','  Tên vật phẩm: '+n];
    SECS.forEach(s=>{const v=String(vals[s[0]]||'').trim();if(!v)out.push(s[0]+':\n  - Chờ bổ sung');else out.push(s[0]+':\n'+v.split('\n').map(l=>(l.indexOf('  ')===0?l:'  '+l)).join('\n'))});
    return out.join('\n');
  }

  /* ===== Mục lục ===== */
  function shortDesc(it){
    const pick=t=>{const ls=String(t||'').split('\n').map(l=>l.replace(/^[-*•\s]+/,'').trim()).filter(Boolean);return ls.length?ls[0]:''};
    let s=pick(it.sections['Hiệu ứng cốt lõi'])||pick(it.sections['Cơ chế & Cách dùng'])||pick(it.sections['Thông tin cơ bản']);
    s=s.replace(/^[^:：]{1,8}[:：]\s*/,'').replace(/[|｜\[\]【】]/g,'').replace(/\s+/g,' ').trim();
    return s.length>90?s.slice(0,90)+'…':s;
  }
  const buildSimple=l=>{const mx=l.length?l[l.length-1].code:'150';return '## I.【Mục lục đơn giản】001～'+mx+' Danh sách tên đạo cụ\n\n```\n'+l.map(i=>i.code+'. '+i.title).join('\n')+'\n```'};
  function buildCatDir(l){
    const out=['## II.【Danh mục tra cứu tám phân loại lối chơi】',''];
    ['cat_1','cat_2','cat_3','cat_4','cat_5','cat_6','cat_7','cat_8'].forEach(id=>{
      const arr=l.filter(i=>i.categoryId===id),d=CAT_DESC[id];
      out.push('**'+d[0].replace(/（.*?）$/,'')+'（'+arr.length+' món）**');out.push(d[1]);out.push('```');
      if(arr.length)arr.forEach(i=>out.push(i.code+'. '+i.title));else out.push('（Chưa có）');
      out.push('```');out.push('');
    });
    return out.join('\n').trim();
  }
  function buildDetailDir(old,l){
    const om={};String(old||'').split('\n').forEach(ln=>{const m=ln.trim().match(/^([0-9]{3})\.[ \t]*(.+)$/);if(m)om[m[1]]=ln.trim()});
    const mx=l.length?l[l.length-1].code:'150';
    const lines=l.map(i=>{if(om[i.code])return om[i.code];const d=shortDesc(i);return i.code+'. '+i.title+(d?'：'+d:'')});
    return '## III.【Danh mục tra cứu nhanh chi tiết】001～'+mx+'\n\n```\n'+lines.join('\n')+'\n```';
  }
  async function updateCatalogs(silent){
    const h=P.TavernHelper;
    if(!worldBook){if(!silent)setCat('Vui lòng đọc Sách thế giới trước');return false}
    if(!h||!h.updateWorldbookWith){if(!silent)setCat('TavernHelper không hỗ trợ ghi vào Sách thế giới');return false}
    const l=items.filter(i=>!i.isLore&&i.code).sort((a,b)=>Number(a.code)-Number(b.code));
    if(!l.length){if(!silent)setCat('Không có đạo cụ nào để ghi vào danh mục');return false}
    if(!silent)setCat('Đang cập nhật ba thư mục lớn…');
    const hit={s:0,c:0,d:0};
    try{
      const upd=await h.updateWorldbookWith(worldBook,wb=>wb.map(e=>{
        const c=String(e.content||''),cm=String(e.comment||e.name||'');
        const iS=c.indexOf('【Mục lục đơn giản】')>=0||c.indexOf('Danh sách tên đạo cụ đơn giản')>=0||cm.indexOf('Mục lục đơn giản')>=0||cm.indexOf('Danh mục sơ lược')>=0;
        const iC=c.indexOf('Danh mục tra cứu tám phân loại lối chơi')>=0||c.indexOf('Danh mục tra cứu tám loại chơi chính')>=0||cm.indexOf('Phân loại')>=0;
        const iD=c.indexOf('【Danh mục tra cứu nhanh chi tiết】')>=0||c.indexOf('【Mục lục tra cứu chi tiết】')>=0||cm.indexOf('Tra cứu nhanh chi tiết')>=0||cm.indexOf('Danh mục đạo cụ')>=0;
        if(iS&&!iC&&!iD){hit.s++;return Object.assign({},e,{content:buildSimple(l)})}
        if(iC&&!iS&&!iD){hit.c++;return Object.assign({},e,{content:buildCatDir(l)})}
        if(iD&&!iS&&!iC){hit.d++;return Object.assign({},e,{content:buildDetailDir(c,l)})}
        return e;
      }));
      if(Array.isArray(upd))allEntries=upd;
      items=allEntries.map(parseEntry);
      if(selected)selected=items.find(i=>i.uid===selected.uid)||selected;
      renderList();
      const msg='✔ Danh mục đã được cập nhật lên '+l[l.length-1].code+'（Đơn giản '+hit.s+' / Phân loại '+hit.c+' / Tra nhanh '+hit.d+'）';
      setCat(msg);setSt(msg);return true;
    }catch(err){const m='✘ Cập nhật danh mục thất bại：'+(err&&err.message?err.message:String(err));setCat(m);setSt(m);return false}
  }
  function setCat(m){try{const e=$('.catst');if(e)e.textContent=m||''}catch(_){}try{setSt(m)}catch(_){}}

  /* ===== Trang hàng hóa ===== */
  function renderCats(){catSel.replaceChildren();CATS.forEach(c=>{const o=el('option','',c.name);o.value=c.id;catSel.append(o)});catSel.value=category}
  function filtered(){
    const q=qIn.value.trim().toLowerCase(),s=sortSel.value;
    const arr=items.filter(it=>{
      if(category==='lore')return it.isLore;
      if(category==='fav')return favs.has(it.code||String(it.uid));
      if(category!=='all'){if(it.isLore)return false;if(it.categoryId!==category)return false}
      else if(it.isLore&&!q)return false;
      if(!q)return true;
      return (it.code+' '+it.title+' '+it.tags.join(' ')+' '+it.raw).toLowerCase().indexOf(q)>=0;
    });
    arr.sort((a,b)=>{
      if(a.isLore!==b.isLore)return a.isLore?1:-1;
      if(s==='code_desc')return (Number(b.code)||0)-(Number(a.code)||0);
      if(s==='name_asc')return a.title.localeCompare(b.title,'zh-CN');
      return (Number(a.code)||9999)-(Number(b.code)||9999);
    });
    return arr;
  }
  function renderList(){
    ilist.replaceChildren();
    const arr=filtered();
    if(!arr.length){ilist.append(el('div','hint','Không có mục khớp'));return}
    arr.forEach(it=>{
      const b=el('button','item'+(selected&&selected.uid===it.uid?' on':''));
      b.type='button';
      b.append(el('span','item-code',(it.code||'◈')+'.'));
      b.append(el('span','item-name',it.title));
      b.addEventListener('click',w(()=>selectItem(it),'Chọn đạo cụ'));
      ilist.append(b);
    });
  }
  function selectItem(it){
    selected=it;submode='';renderList();
    emptyV.hidden=true;detailV.hidden=false;
    hcode.textContent=it.code||'LORE';htitle.textContent=it.title;
    const k=it.code||String(it.uid),isf=favs.has(k);
    favB.classList.toggle('on',isf);favB.textContent=isf?'★ Đã lưu':'☆ Yêu thích';
    htags.replaceChildren();
    htags.append(el('span','cat-badge',it.categoryName));
    const en=el('label','en'),chk=el('input');chk.type='checkbox';
    chk.checked=it.entry.enabled!==undefined?!!it.entry.enabled:!it.entry.disable;
    chk.addEventListener('change',w(async()=>{
      if(!worldBook)return;const h=P.TavernHelper;if(!h||!h.updateWorldbookWith)return;
      const upd=await h.updateWorldbookWith(worldBook,wb=>wb.map(e=>e.uid===it.uid?Object.assign({},e,{enabled:chk.checked,disable:!chk.checked}):e));
      allEntries=upd;items=allEntries.map(parseEntry);selected=items.find(i=>i.uid===it.uid)||selected;
      setSt('Đã '+(chk.checked?'Bật':'Tắt')+'：'+selected.title);
    },'Chuyển đổi kích hoạt'));
    en.append(chk,D.createTextNode('Kích hoạt'));htags.append(en);
    it.tags.slice(0,10).forEach(t=>htags.append(el('span','tag',t)));
    smchips.replaceChildren();
    if(it.submodes.length){
      smbar.hidden=false;
      it.submodes.forEach(m=>{
        const c=el('button','chip',m);c.type='button';
        c.addEventListener('click',()=>{
          const was=submode===m;submode=was?'':m;
          smchips.querySelectorAll('.chip').forEach(x=>x.classList.remove('on'));
          if(!was)c.classList.add('on');
        });
        smchips.append(c);
      });
    }else smbar.hidden=true;
    agrid.replaceChildren();
    ACTS.forEach(p=>{
      const b=el('button','act',p.label);b.type='button';b.title=p.title;
      b.addEventListener('click',w(()=>{
        const txt=p.build(it,tgIn.value.trim(),exIn.value.trim(),submode);
        prevB.hidden=false;ptext.value=txt;fillInput(txt);
      },'Tạo lệnh'));
      agrid.append(b);
    });
    secsB.replaceChildren();
    let n=0;
    SECS.forEach((d,i)=>{
      const c=it.sections[d[0]];if(!c)return;n++;
      const dt=el('details','sec');dt.open=i<2;
      dt.append(el('summary','',d[2]+' '+d[1]));
      dt.append(el('div','',c.replace(/^ {2}/gm,'')));
      secsB.append(dt);
    });
    if(!n){const dt=el('details','sec');dt.open=true;dt.append(el('summary','','◈ Hồ sơ gốc'));dt.append(el('div','',it.raw||'（Mục trống）'));secsB.append(dt)}
  }
  function fillInput(text){
    const input=D.querySelector('#send_textarea, textarea#send_textarea, textarea[name="message"]');
    if(!input){setSt('Không phát hiện ô nhập, lệnh đã ở trong ô xem trước');return}
    const sep=input.value&&!/[\r\n]$/.test(input.value)?'\n':'';
    input.value=input.value+sep+text;
    input.dispatchEvent(new Event('input',{bubbles:true}));
    input.dispatchEvent(new Event('change',{bubbles:true}));
    input.focus();
    setSt('Đã điền：'+(selected?selected.title:''));
  }
  async function loadBook(pref){
    setSt('Đang tìm kiếm Sách thế giới【Mạng lười dâm khiếu】…');
    try{
      const h=P.TavernHelper;
      if(!h||!h.getWorldbookNames||!h.getWorldbook)throw new Error('Không phát hiện interface Sách thế giới của trợ lý quán rượu');
      const names=h.getWorldbookNames()||[];
      book.replaceChildren();names.forEach(n=>{const o=el('option','',n);o.value=n;book.append(o)});
      let bk=pref;
      if(!bk||names.indexOf(bk)<0)bk=names.find(n=>BOOK_KEYWORDS.some(k=>String(n).toLowerCase().indexOf(k.toLowerCase())>=0))||names[0]||'';
      if(!bk)throw new Error('Không tìm thấy Sách thế giới trong quán rượu');
      worldBook=bk;book.value=bk;
      const raw=await h.getWorldbook(bk);
      allEntries=Array.isArray(raw)?raw:[];
      items=allEntries.map(parseEntry);
      renderCats();renderList();
      const f=filtered()[0];if(f)selectItem(f);
      setSt('Đã kết nối《'+bk+'》 · '+items.filter(i=>!i.isLore).length+' món tạo vật');
      renderIPick();renderUPick();renderGbTargets();
      if(page==='shop')renderWbSection();
    }catch(e){setSt('Kết nối thất bại：'+(e&&e.message?e.message:String(e)))}
  }

  /* ===== Bao bọc chung ===== */
  function w(fn,label){return function(){try{return fn.apply(this,arguments)}catch(e){console.error('[SV] '+label,e);setSt('⚠ '+label+' Bị lỗi：'+(e&&e.message?e.message:String(e)))}}}

  /* personas Thêm trường nạp（Phải ở loadDb Thực thi trước） */
  if(!TYPES.personas.fields.some(f=>f[0]==='loaded'))TYPES.personas.fields=TYPES.personas.fields.concat([['loaded','Trạng thái tải']]);

  /* ===== Thẻ hồ sơ thông dụng ===== */
  function buildDet(rec,fields,opt){
    opt=opt||{};
    const d=el('details','det'),sum=el('summary');
    const nm=el('span','det-name','【'+(rec.name||'Chưa đặt tên')+'】');
    sum.append(nm);
    if(opt.src)sum.append(el('span','det-src',opt.src));
    if(opt.onDel){const x=el('b','det-del','×');x.addEventListener('click',ev=>{ev.preventDefault();ev.stopPropagation();w(opt.onDel,'Xóa hồ sơ')()});sum.append(x)}
    d.append(sum);
    const body=el('div','det-body');
    fields.forEach(f=>{
      const lab=el('label','det-field');lab.append(el('span','',f[1]));
      const long=f[0]!=='name'&&f[0]!=='rarity';
      const inp=long?el('textarea','det-f'):el('input','det-f');
      if(long)inp.rows=2;
      inp.value=rec[f[0]]||'';
      inp.addEventListener('input',()=>{
        rec[f[0]]=inp.value;
        if(f[0]==='name')nm.textContent='【'+(inp.value||'Chưa đặt tên')+'】';
        if(opt.onChg)try{opt.onChg()}catch(_){}
      });
      lab.append(inp);body.append(lab);
    });
    d.append(body);return d;
  }

  /* ===== TYPE-θ Thẻ nhân cách đồng vị ===== */
  const TH_FIELDS=[['bi_id','Thân phận'],['bi_look','Ngoại hình'],['bi_skill','Năng lực'],['bi_rel','Quan hệ'],['bi_other','Khác']];
  const TH_NA=[['na_self','Nhận thức bản thân'],['na_need','Nhu cầu cốt lõi'],['na_goal','Mục tiêu hiện tại'],['na_arc','Hành trình quá khứ'],['na_trait','Đặc điểm phát triển'],['na_future','Xu hướng tương lai']];
  function thLamp(r){let n=+r||0;if(!isFinite(n)||n<0)n=0;n=Math.min(3,Math.floor(n));return n?Array(n+1).join('θ'):'—'}
  function buildPersonaCard(rec,opt){
    opt=opt||{};
    const loaded=rec.loaded==='1'||rec.loaded===true;
    const card=el('div','theta-card');
    const head=el('div','theta-head');
    const r1=el('div','theta-r1');
    r1.append(el('div','theta-name','▣ '+(rec.name||'Đồng vị chưa đặt tên')));
    r1.append(el('div','theta-lamp',thLamp(rec.rarity)));
    const con=el('div','theta-concept',rec.concept||'（Chưa điền khái niệm nhân cách）');
    const r2=el('div','theta-r2');
    const ctrl=el('div','theta-ctrl');
    const st=el('div','hud-st'+(loaded?' on':''),loaded?'Đã nạp':'Chưa nạp');
    const sw=el('div','hud-sw'+(loaded?' on':''));
    sw.append(el('span','hud-sw-k'));
    const paint=on=>{
      st.textContent=on?'Đã nạp':'Chưa nạp';st.classList.toggle('on',on);
      sw.classList.toggle('on',on);
      rec.loaded=on?'1':'';
      saveDb();
      if(opt.onChg)try{opt.onChg()}catch(_){}
    };
    sw.addEventListener('click',e=>{e.preventDefault();e.stopPropagation();paint(!(rec.loaded==='1'))});
    st.addEventListener('click',e=>{e.preventDefault();e.stopPropagation();paint(!(rec.loaded==='1'))});
    ctrl.append(st,sw);
    const chg=el('button','theta-actbtn','✎ Biên soạn');chg.type='button';
    chg.addEventListener('click',e=>{e.preventDefault();e.stopPropagation();body.hidden=!body.hidden});
    ctrl.append(chg);
    if(opt.onDel){
      const del=el('button','theta-actbtn','✕ Tiêu hủy');del.type='button';
      del.addEventListener('click',e=>{e.preventDefault();e.stopPropagation();w(opt.onDel,'Xóa')()});
      ctrl.append(del);
    }
    const gun=el('button','theta-actbtn','🔫 Lắp đặt Súng Truyền Động');gun.type='button';
    gun.addEventListener('click',e=>{
      e.preventDefault();e.stopPropagation();
      paint(true);
      if(opt.onChg)try{opt.onChg()}catch(_){}
      const who=opt.ownerName||(curT()?curT().name:'Mục tiêu');
      const txt='*'+U+' Rút ra từ khe nứt hư không「'+rec.name+'」lá bài của, cắm nó vào khe thẻ phía trên súng điều khiển —— bóp cò cùng hiệu ứng âm thanh chói tai 「Điều khiển hình thái! Ghi đè nhân cách!」. Dòng lũ dữ liệu hologram 3D phun trào từ họng súng, giữa những đoạn mã lỗi và hồ quang điện đã ghi đè lên '+who+' trang phục và một phần cấu tạo thể xác. Ý thức thực tại của cô ấy bị đẩy vào phòng cách ly an toàn, còn nhân cách đến từ thế giới song song「'+(rec.concept||rec.name)+'」Nhân cách chính thức tiếp quản thân xác này。*';
      fillInput(txt);
    });
    const brk=el('button','theta-actbtn','💥 Đột phá nhân cách');brk.type='button';
    brk.addEventListener('click',e=>{
      e.preventDefault();e.stopPropagation();
      const who=opt.ownerName||(curT()?curT().name:'Mục tiêu');
      const txt='*'+U+' Bóp giữ cò súng điều khiển để tụ lực, tiếng bíp quá tải xé toạc không khí —— 「Đột phá nhân cách」. Nhân cách gốc vốn bị giam cầm trong phòng cách ly an toàn bị dòng lũ dữ liệu cuồng bạo bóc tách thô bạo khỏi trung khu thần kinh, khe hất vỏ đạn cùng tiếng van khí áp suất cao gầm rú bật ra một lá bài tỏa ánh sáng trắng yếu ớt【Nhân cách nguyên bản·Thẻ bài】。'+who+' thể xác hoàn toàn về không, của thế giới khác「'+(rec.concept||rec.name)+'」Trở thành chủ nhân hợp pháp duy nhất của thân thể này。*';
      fillInput(txt);
    });
    ctrl.append(gun,brk);
    r2.append(ctrl);
    head.append(r1,con,r2);
    card.append(head);

    const body=el('div','theta-body');body.hidden=true;
    const mkRow=(k,v)=>{
      const rr=el('div','theta-row');
      rr.append(el('b','theta-k',k));
      const ta=el('div','theta-v',v||'—');
      rr.append(ta);return rr;
    };
    const mkEdit=(f,label)=>{
      const lab=el('label','det-field',label);
      const long=f[0]!=='rarity';
      const inp=long?el('textarea','det-f'):el('input','det-f');
      if(long)inp.rows=2;
      inp.value=rec[f[0]]||'';
      inp.addEventListener('input',()=>{rec[f[0]]=inp.value;saveDb();if(opt.onChg)try{opt.onChg()}catch(_){}});
      lab.append(inp);return lab;
    };
    body.append(mkRow('Tên thẻ',rec.name||'—'));
    body.append(mkRow('Số đèn',thLamp(rec.rarity)!=='—'?thLamp(rec.rarity):'—'));
    body.append(mkRow('Khái niệm',rec.concept||'—'));
    TH_FIELDS.forEach(f=>body.append(mkRow(f[1],rec[f[0]]||'—')));
    TH_NA.forEach(f=>body.append(mkRow(f[1],rec[f[0]]||'—')));
    const his=el('div','');
    const hlines=String(rec.history||'').split('\n').map(s=>s.trim()).filter(Boolean);
