      const b=el('div','chitem',(i<5?'▸ Thời gian dài '+(i+1)+' · ':'▸ Bản chụp nhanh '+(i-4)+' · ')+h);
      his.append(b);
    });
    else his.append(el('div','chitem','（Chưa ghi lại lịch sử song song）'));
    const hisBox=el('div','');hisBox.append(el('div','csec','Lịch sử song song // PARALLEL HISTORY'),his);
    body.append(hisBox);
    const editBox=el('div','');
    editBox.append(el('div','csec','Biên soạn trường dữ liệu'));
    editBox.append(mkEdit(['name','Tên thẻ'],'Tên thẻ（Tên·Tổ chức·Chức vụ）'));
    editBox.append(mkEdit(['rarity','Số đèn'],'Số đèn（0~3）'));
    editBox.append(mkEdit(['concept','Khái niệm nhân cách'],'Khái niệm nhân cách（Định ngữ+Thân phận）'));
    TH_FIELDS.forEach(f=>editBox.append(mkEdit(f,f[1])));
    TH_NA.forEach(f=>editBox.append(mkEdit(f,f[1])));
    editBox.append(mkEdit(['history','Lịch sử song song'],'Lịch sử song song（Mỗi dòng một mục: 5 đoạn dài+2 Bản chụp nhanh）'));
    body.append(editBox);
    card.append(body);
    return card;
  }

  /* ===== Danh sách hồ sơ gắn kèm ===== */
  function renderHolderList(box,type,holder,onChg){
    if(!box)return;
    const def=TYPES[type];
    const ids=(holder.refs&&holder.refs[type])||[];
    const list=lib(type).filter(e=>ids.indexOf(e.id)>=0);
    box.replaceChildren();
    if(!list.length){box.append(el('div','hint','Chưa có「'+def.label+'」——Nhấn thêm mới ở dưới, hoặc vào 【Kho】 để chỉ định mục đến'));return}
    if(type==='personas'){
      const loadedN=list.filter(r=>r.loaded==='1'||r.loaded===true).length;
      const banner=el('div','theta-banner');
      banner.textContent=loadedN===0
        ?'【Ghi chú trang bị】Mục tiêu chưa nạp bất kỳ nhân cách nào, hãy miêu tả dáng vẻ cơ thể cô ấy biến thành thể xác vô thức, mắt khép hờ, nhịp thở đều đặn。'
        :(loadedN===1
          ?'【Ghi chú trang bị】Mục tiêu đã nạp 1 nhân cách, hãy miêu tả hành động của họ theo tư liệu nhân cách đó。'
          :'【Ghi chú trang bị】Mục tiêu đang ở trạng thái đa nhân cách cộng tồn, đã tải '+loadedN+' nhân cách, vui lòng miêu tả sự cộng tồn giữa các nhân cách/dáng vẻ tranh giành。');
      box.append(banner);
      list.forEach(r=>box.append(buildPersonaCard(r,{ownerName:holder.name||'Mục tiêu',onChg,onDel:()=>{det(holder,type,r.id);saveDb();onChg()}})));
      return;
    }
    list.forEach(r=>box.append(buildDet(r,def.fields,{onChg:saveDb,onDel:()=>{det(holder,type,r.id);saveDb();onChg()}})));
