  function ensureEntry(h,type,name){
    const def=TYPES[type];if(!def||!h)return false;
    const ex=lib(type).find(x=>x.name===name);
    if(ex){att(h,type,ex.id);return true}
    const o={id:uid()};def.fields.forEach(f=>o[f[0]]='');o.name=name;
