  function routeAdd(it,label,from){
    const sp=it.code&&SPECIAL[it.code];
    if(!sp)return 'Đã thêm「'+label+'」';
    if(sp.kind==='rule'){
      if(!db.records.rules.some(r=>r.name===it.title)){
        db.records.rules.push({id:uid(),type:RULES[sp.type]?sp.type:'Quy tắc khác',active:true,name:it.title,target:'',terms:'',effect:''});
        saveDb();if(page==='records')renderRecords();
      }
      return sp.tip;
    }
    if(sp.kind==='user'){if(ensureEntry(db.user,sp.type,it.title)){saveDb();if(page==='user')renderUDetail()}return sp.tip}
    if(sp.kind==='skill'){
      if(from==='user'){if(ensureEntry(db.user,'skills',it.title)){saveDb();if(page==='user')renderUDetail()}}
      else{const t=curT();if(t&&ensureEntry(t,'skills',it.title)){saveDb();if(page==='targets')renderTDetail()}}
      return sp.tip;
    }
    const t=curT();
    if(!t)return 'Đã thêm「'+label+'」（Chưa chọn mục tiêu, không thể tạo hồ sơ）';
    if(sp.kind==='target'&&ensureEntry(t,sp.type,it.title)){saveDb();if(page==='targets')renderTDetail()}
    return sp.tip;
  }
