  /* ===== AI ===== */
  function presetNames(){const f=apiFn('getPresetNames');try{return f?(f()||[]).filter(n=>n!=='in_use'):[]}catch(_){return[]}}
  function loadedPreset(){const f=apiFn('getLoadedPresetName');try{return f?(f()||''):''}catch(_){return''}}
  function profiles(){
    const c=stCtx();
    try{const s=c&&c.ConnectionManagerRequestService;if(s&&typeof s.getSupportedProfiles==='function')return s.getSupportedProfiles()||[]}catch(_){}
    try{return (c&&c.extensionSettings&&c.extensionSettings.connectionManager&&c.extensionSettings.connectionManager.profiles)||[]}catch(_){return[]}
  }
  async function reqPreset(u,s){
    const gen=apiFn('generate'),raw=apiFn('generateRaw');
    const inj={role:'system',content:s,position:'in_chat',depth:0,should_scan:false};
    if(gen){
      const cfg={user_input:u,should_stream:false,should_silence:true,max_chat_history:0,injects:[inj]};
      if(api.presetName)cfg.preset_name=api.presetName;
      const r=await gen(cfg);
      const t=typeof r==='string'?r:((r&&r.content)||'');
      if(!t.trim())throw new Error('Preset trả về rỗng');
      return t;
    }
    if(raw){
      const r=await raw({user_input:u,ordered_prompts:[{role:'system',content:s}],overrides:{world_info_before:'',world_info_after:'',chat_history:{prompts:[],with_depth_entries:false}},should_silence:true});
      const t=String(r||'');
      if(!t.trim())throw new Error('generateRaw Dữ liệu trả về trống');
      return t;
    }
    throw new Error('Tavern Helper chưa cung cấp generate / generateRaw');
  }
  async function reqProfile(u,s){
    const c=stCtx();if(!c)throw new Error('Không thể truy cập ngữ cảnh quán rượu');
    const svc=c.ConnectionManagerRequestService;
    if(!svc||typeof svc.sendRequest!=='function')throw new Error('Quán rượu không hỗ trợ gọi cấu hình kết nối');
    const id=api.profileId||(c.extensionSettings&&c.extensionSettings.connectionManager&&c.extensionSettings.connectionManager.selectedProfile);
    if(!id)throw new Error('Quán rượu chưa chọn cấu hình kết nối');
    const r=await svc.sendRequest(id,[{role:'system',content:s},{role:'user',content:u}],Number(api.maxTokens)||3600,{stream:false,extractData:true});
    const t=typeof r==='string'?r:((r&&r.content)||'');
    if(!t.trim())throw new Error('Cấu hình kết nối trả về trống');
    return t;
  }
  async function reqCustom(u,s){
    const ep=String(api.endpoint||'').trim().replace(/\/$/,'');
    if(!ep)throw new Error('Chưa điền địa chỉ endpoint');
    if(!api.model)throw new Error('Chưa điền tên model');
    const body={model:api.model,messages:[{role:'system',content:s},{role:'user',content:u}],temperature:Number(api.temp)||.85,max_tokens:Number(api.maxTokens)||3600,stream:false};
    if(api.noThink)body.reasoning_effort='none';
    const r=await fetch(ep+'/chat/completions',{method:'POST',headers:Object.assign({'Content-Type':'application/json'},api.key?{Authorization:'Bearer '+api.key}:{}),body:JSON.stringify(body)});
    if(!r.ok)throw new Error('HTTP '+r.status);
    const d=await r.json();
    const t=String((d.choices&&d.choices[0]&&d.choices[0].message&&d.choices[0].message.content)||'');
    if(!t.trim())throw new Error('Giao diện tùy chỉnh trả về rỗng');
    return t;
  }
  async function callAI(u,s){
    const order=[];const push=m=>{if(order.indexOf(m)<0)order.push(m)};
    push(api.mode);push('preset');push('profile');push('custom');
    const errs=[];
    for(const m of order){
      try{
        const t=m==='preset'?await reqPreset(u,s):m==='profile'?await reqProfile(u,s):await reqCustom(u,s);
        const raw=$('.apiraw');if(raw)raw.value=t;
        return t;
      }catch(e){errs.push(m+'：'+(e&&e.message?e.message:e))}
    }
    throw new Error(errs.join('；'));
  }
  function splitLabel(line,fields){
    const t=String(line).trim();
    for(const f of fields){if(t.indexOf(f[1])===0){return {key:f[0],val:t.slice(f[1].length).replace(/^[\s:：]+/,'')}}}
    return null;
  }
  function parseBlock(body,fields){
    const out={};fields.forEach(f=>out[f[0]]='');
    let cur=null;
    String(body||'').split('\n').forEach(ln=>{
      const h=splitLabel(ln,fields);
      if(h){cur=h.key;out[cur]=h.val}
      else if(cur&&ln.trim())out[cur]=out[cur]?out[cur]+'\n'+ln.trim():ln.trim();
    });
    return out;
  }
  function parseBlocks(raw,fields){
    const res=[];const re=/===ENTRY_START===([\s\S]*?)===ENTRY_END===/g;let m;
    while((m=re.exec(raw))!==null)res.push(parseBlock(m[1],fields));
    if(!res.length){
      const i=String(raw||'').indexOf('===ENTRY_START===');
      if(i>=0){const one=parseBlock(String(raw).slice(i+18),fields);if(Object.keys(one).some(k=>String(one[k]||'').trim()))res.push(one)}
    }
    return res.filter(o=>Object.keys(o).some(k=>String(o[k]||'').trim()));
  }

