      if(!f){inp.remove();return}
      const rd=new FileReader();
      rd.onload=()=>{
        try{applyPackJson(JSON.parse(rd.result))}
        catch(e){setCat('Phân tích gói thất bại：'+(e&&e.message?e.message:e))}
        inp.remove();
      };
