  function applyPackJson(pack){
    if(!pack||pack.type!==PACK_TYPE)throw new Error('Không phải gói cập nhật xuất từ thiết bị đầu cuối này');
    const wbIn=Array.isArray(pack.wb)?pack.wb:[];
    let added=0,updated=0;
    const warns=[];
    wbIn.forEach(r=>{
      const nm=String(r.name||'').trim();
      const code=String(r.code||'').trim();
      if(!nm)return;
      const sameName=lib(WB_TYPE).find(x=>String(x.name||'').trim()===nm);
      if(sameName){
        const oldCode=String(sameName.code||'').trim();
        if(code&&oldCode&&code!==oldCode)warns.push('「'+nm+'」Số thứ tự '+oldCode+' → '+code);
        TYPES[WB_TYPE].fields.forEach(f=>sameName[f[0]]=String(r[f[0]]||''));
        if(!sameName.strategy)sameName.strategy='selective';
        if(!sameName.order)sameName.order='100';
        updated++;return;
      }
      const sameCode=code?lib(WB_TYPE).find(x=>String(x.code||'').trim()===code):null;
      const o={id:uid(),target:''};
      TYPES[WB_TYPE].fields.forEach(f=>o[f[0]]=String(r[f[0]]||''));
      o.strategy=o.strategy==='constant'?'constant':'selective';
      if(!o.order)o.order='100';
      if(!o.code){
        const hit=items.find(i=>String(i.title||'').trim()===nm);
        if(hit)o.code=String(hit.code||'');
      }
      if(sameCode){
        o.code='';
        warns.push('Số thứ tự #'+code+' đã bị Khu vực thả「'+(sameCode.name||'Chưa đặt tên')+'」chiếm dụng, nhập vào「'+nm+'」Đổi thành chờ phân bổ');
      }
      db.lib[WB_TYPE].push(o);added++;
    });
    let dAdd=0;
    CORE.forEach(t=>{
      ((pack.derived&&pack.derived[t])||[]).forEach(r=>{
        if(!r||!String(r.name||'').trim())return;
        const o={id:uid()};
        TYPES[t].fields.forEach(f=>o[f[0]]=String(r[f[0]]||''));
        if(t==='personas')o.loaded='';
        (db.lib[t]||(db.lib[t]=[])).push(o);dAdd++;
      });
    });
    persistWb();saveDb();
    renderWbSection();renderRecords();focusDropZone();
    let msg='Nhập hoàn tất: Thêm mới '+added+' mục / Cập nhật mục trùng tên '+updated+' mục / Thêm mục phái sinh '+dAdd+' mục。';
    if(warns.length)msg+=' ⚠ '+warns.length+' chỗ xung đột số thứ tự：'+warns.slice(0,6).join('；')+(warns.length>6?' v.v.':'');
    setCat(msg);setSt(msg);
  }
  function confirmCoverTarget(rec,sel){
    const val=String(sel.value||'');
    if(!val){rec.target='';persistWb();return}
    const hit=items.find(i=>String(i.uid)===String(val));
    if(!hit){rec.target=val;persistWb();return}
    const nm=String(rec.name||'').trim()||'（Chưa đặt tên）';
    const tn=String(hit.title||'').trim()||'（Chưa đặt tên）';
    const same=nm===tn;
    const tip='Sắp ghi mục này trong Khu vực thả vào Sách thế giới：\n\n'
      +'Mục Khu vực thả：'+nm+'\n'
      +'Ghi đè mục tiêu：#'+hit.code+'  '+tn+'\n\n'
      +(same?'Tên trùng khớp。':'\n⚠ Tên không khớp! Hãy xác nhận số hiệu không bị lệch。\n')
      +'Bạn có chắc muốn ghi đè「'+tn+'」không？';
    if(!P.confirm(tip)){sel.value=rec.target||'';return}
    rec.target=val;persistWb();
  }



