  let dvSel=new Map();
  let dvSeen=new Map();
  let dvRuleSel=new Set(),dvRuleSeen=new Set();
  function dvInit(){
    dvSel=new Map();dvSeen=new Map();
    dvRuleSel=new Set();dvRuleSeen=new Set();
    try{((db.records&&db.records.rules)||[]).forEach(r=>{if(r&&r.id){dvRuleSel.add(r.id);dvRuleSeen.add(r.id)}})}catch(_){}
    CORE.forEach(t=>{
      const ids=(db.lib[t]||[]).map(r=>r.id);
      dvSel.set(t,new Set(ids));
      dvSeen.set(t,new Set(ids));
    });
  }
  function dvCount(t){const s=dvSel.get(t);return s?s.size:0}
  function dvTotal(){let n=0;CORE.forEach(t=>{n+=dvCount(t)});return n}
  function renderDvPick(){
    const box=$('.dvpick');
    if(!box){try{console.warn('[X] dvpick Không tìm thấy vùng chứa')}catch(_){};return}
    try{
      const open=new Set();
      Array.from(box.querySelectorAll('details.dvgroup[open]')).forEach(d=>{if(d.dataset.type)open.add(d.dataset.type)});
      const scrollTop=box.scrollTop||0;
      box.replaceChildren();
      const libOf=t=>{
        try{ if(db&&db.lib&&Array.isArray(db.lib[t]))return db.lib[t] }catch(_){}
        return [];
      };
      let total=0,types=0;
      CORE.forEach(t=>{const n=libOf(t).length;if(n)types++;total+=n});
      box.append(el('div','dvhead','Hiện có trong kho '+types+' loại · '+total+' mục'));
      CORE.forEach(t=>{
        const def=TYPES[t];
        if(!def)return;
        const list=libOf(t);
        if(!dvSel.has(t))dvSel.set(t,new Set());
        if(!dvSeen.has(t))dvSeen.set(t,new Set());
        const curSet=dvSel.get(t),seenSet=dvSeen.get(t);
        list.forEach(r=>{
          if(r&&r.id&&!seenSet.has(r.id)){seenSet.add(r.id);curSet.add(r.id)}
        });
        const det=el('details','dvgroup'+(list.length?'':' dvempty'));
        det.dataset.type=t;
        if(open.has(t))det.open=true;
        const sum=el('summary','dvsum');
        sum.append(el('span','dvico',(def.icon||'')+' '+(def.label||t)));
        sum.append(el('span','dvcnt',dvCount(t)+'/'+list.length));
        det.append(sum);
        const tools=el('div','dvtools');
        const bAll=el('button','dvmini','Chọn hết loại này');bAll.type='button';
        bAll.addEventListener('click',e=>{e.preventDefault();e.stopPropagation();dvSel.set(t,new Set(list.map(r=>r.id)));renderDvPick()});
        const bNone=el('button','dvmini','Xóa trống loại này');bNone.type='button';
        bNone.addEventListener('click',e=>{e.preventDefault();e.stopPropagation();dvSel.set(t,new Set());renderDvPick()});
        tools.append(bAll,bNone);det.append(tools);
        if(!list.length){
          det.append(el('div','tagempty','Thể loại này chưa có mục nào'));
        }else{
          list.forEach(r=>{
            if(!r)return;
            const lab=el('label','dvitem');
            const cb=el('input');cb.type='checkbox';
            const cur=dvSel.get(t);
            cb.checked=cur?cur.has(r.id):false;
            cb.addEventListener('change',()=>{
              if(!dvSel.has(t))dvSel.set(t,new Set());
              const s=dvSel.get(t);
              if(cb.checked)s.add(r.id);else s.delete(r.id);
              const cEl=det.querySelector('.dvcnt');
              if(cEl)cEl.textContent=dvCount(t)+'/'+list.length;
            });
            lab.append(cb,el('span','dvname2',String(r.name||'Chưa đặt tên')));
            det.append(lab);
          });
        }
        box.append(det);
      });
      try{
        const rules=(db.records&&Array.isArray(db.records.rules))?db.records.rules:[];
        rules.forEach(r=>{if(r&&r.id&&!dvRuleSeen.has(r.id)){dvRuleSeen.add(r.id);dvRuleSel.add(r.id)}});
        const rdet=el('details','dvgroup'+(rules.length?'':' dvempty'));
        rdet.dataset.type='__rules';
        if(open.has('__rules'))rdet.open=true;
        const rsum=el('summary','dvsum');
        rsum.append(el('span','dvico','⚙ Quy tắc thế giới'));
        rsum.append(el('span','dvcnt',dvRuleSel.size+'/'+rules.length));
        rdet.append(rsum);
        const rtools=el('div','dvtools');
        const rAll=el('button','dvmini','Chọn tất cả mục này');rAll.type='button';
        rAll.addEventListener('click',e=>{e.preventDefault();e.stopPropagation();dvRuleSel=new Set(rules.map(r=>r.id));renderDvPick()});
        const rNone=el('button','dvmini','Xóa trống mục này');rNone.type='button';
        rNone.addEventListener('click',e=>{e.preventDefault();e.stopPropagation();dvRuleSel=new Set();renderDvPick()});
        rtools.append(rAll,rNone);rdet.append(rtools);
        if(!rules.length)rdet.append(el('div','tagempty','Thể loại này chưa có mục nào'));
        else rules.forEach(r=>{
          const lab=el('label','dvitem');
          const cb=el('input');cb.type='checkbox';cb.checked=dvRuleSel.has(r.id);
          cb.addEventListener('change',()=>{
            if(cb.checked)dvRuleSel.add(r.id);else dvRuleSel.delete(r.id);
            const cEl=rdet.querySelector('.dvcnt');
            if(cEl)cEl.textContent=dvRuleSel.size+'/'+rules.length;
          });
          lab.append(cb,el('span','dvname2','['+(r.type||'Quy tắc')+'] '+(r.name||'Chưa đặt tên')));
          rdet.append(lab);
        });
        box.append(rdet);
      }catch(_){}
      box.scrollTop=scrollTop;
    }catch(e){
      try{
        box.replaceChildren();
        box.append(el('div','tagempty','Kết xuất thất bại：'+((e&&e.message)||e)));
      }catch(_){}
      try{console.error('[X] renderDvPick',e)}catch(_){}
    }
  }
