  function exportDerivedPack(){
    const derived={};let n=0,nameless=0;
    CORE.forEach(t=>{
      const ids=dvSel.get(t);
      if(!ids||!ids.size)return;
      const arr=(db.lib[t]||[]).filter(r=>r&&ids.has(r.id)).map(r=>{
        if(!String(r.name||'').trim())nameless++;
        const o={};TYPES[t].fields.forEach(f=>o[f[0]]=String(r[f[0]]||''));return o;
      });
      if(!arr.length)return;
      derived[t]=arr;n+=arr.length;
    });
    const allRules=(db.records&&Array.isArray(db.records.rules))?db.records.rules:[];
    const rules=allRules.filter(r=>dvRuleSel.has(r.id)).map(r=>({
      type:r.type,name:r.name,target:r.target,terms:r.terms,effect:r.effect,active:r.active!==false
    }));
    if(!n&&!rules.length){dvMsg('Không có nội dung để xuất: trong kho chưa có hồ sơ phái sinh, hoặc mỗi danh mục phía trên đều 0/0');return}
    const pack={type:DERIVED_TYPE,v:1,at:new Date().toISOString(),derived,rules};
    const txt=JSON.stringify(pack,null,2);
    let dl='',blobUrl='';
    try{
      const blob=new Blob([txt],{type:'application/json'});
      blobUrl=(typeof URL!=='undefined'&&URL&&URL.createObjectURL)?URL.createObjectURL(blob):('');
      const a=D.createElement('a');
      a.href=blobUrl||('data:application/json;charset=utf-8,'+encodeURIComponent(txt));
      a.download='DERIVED-yj-'+Date.now()+'.json';
      a.rel='noopener';
      a.style.display='none';
      (D.body||D.documentElement).append(a);
      a.click();
      setTimeout(()=>{try{a.remove();if(blobUrl)URL.revokeObjectURL(blobUrl)}catch(_){}},3000);
      dl='，Đã kích hoạt tải xuống';
    }catch(e){dl='，Tải xuống bị chặn：'+((e&&e.message)?e.message:String(e))}
    dvMsg('Đã xuất gói hồ sơ phái sinh: Hồ sơ '+n+' mục / Quy tắc '+rules.length+' mục '+dl
      +(nameless?'（Trong đó '+nameless+' mục chưa viết tên, bên kia khi nhập sẽ bỏ qua, khuyên bạn bổ sung tên trước）':''));
  }
  function pickDerivedPack(){
    const inp=D.createElement('input');
    inp.type='file';inp.accept='.json,application/json';
    inp.style.display='none';
    (D.body||D.documentElement).append(inp);
