  function applyDerivedPack(pack){
    if(!pack||(pack.type!==DERIVED_TYPE&&pack.type!==PACK_TYPE))throw new Error('Gói phái sinh không nhận diện được');
    const derived=pack.derived||{};
    const stat={};let added=0,skip=0;
    Object.keys(derived).forEach(t=>{
      if(!TYPES[t]||t===WB_TYPE)return;
      (derived[t]||[]).forEach(r=>{
        if(!r||!String(r.name||'').trim()){skip++;return}
        const o={id:uid()};
        TYPES[t].fields.forEach(f=>o[f[0]]=String(r[f[0]]||''));
        if(t==='personas')o.loaded='';
        (db.lib[t]||(db.lib[t]=[])).push(o);
        added++;stat[t]=(stat[t]||0)+1;
      });
    });
    let rAdd=0;
    ((pack.rules)||[]).forEach(r=>{
      if(!r)return;
      db.records.rules.push({
        id:uid(),
        type:(typeof RULES!=='undefined'&&RULES[r.type])?r.type:'Quy tắc khác',
        active:r.active!==false,
        name:String(r.name||''),
        target:String(r.target||''),
        terms:String(r.terms||''),
        effect:String(r.effect||'')
      });
      rAdd++;
    });
    saveDb();
    renderRecords();
    renderDvPick();
    const brief=Object.keys(stat).map(t=>TYPES[t].label+' '+stat[t]).join(' / ');
    dvMsg('Nhập gói mở rộng hoàn tất: thêm mới '+added+' mục'+(brief?'（'+brief+'）':'')+(rAdd?' / Quy tắc '+rAdd+' mục':'')
      +(skip?'，Bỏ qua '+skip+' mục chưa viết tên':'')+'，Đã xử lý tất cả như mục mới');
  }
