  function suggestNextCode(){
    const used=new Set(items.filter(i=>!i.isLore).map(i=>String(i.code)));
    let n=Math.max(0,...items.map(i=>Number(i.code)||0))+1;
    let guard=0;
    while(used.has(String(n).padStart(3,'0'))&&guard++<999)n++;
    return String(n).padStart(3,'0');
  }

  function checkCodeDup(rec){
    const code=String(rec.code||'').trim();
    if(!code)return;
    const hit=items.find(i=>String(i.code)===code);
    if(hit&&String(rec.target)!==String(hit.uid)){
      if(P.confirm('Sách thế giới đã chiếm số thứ tự #'+code+'：'+hit.title+'\n\n Bạn có muốn đổi mục này thành「Ghi đè」？\n（Xác nhận＝Ghi đè mục này　Hủy＝Xóa số thứ tự và phân bổ lại）')){
        rec.target=String(hit.uid);
        persistWb();renderWbSection();
        setCat('Đã đem số thứ tự #'+code+' Chỉ định ghi đè「'+hit.title+'」');
      }else{
        rec.code='';
        persistWb();renderWbSection();
        setCat('Đã xóa số thứ tự của mục này, khi ghi sẽ tự động gán số mới');
      }
      return;
    }
    const dup=lib(WB_TYPE).filter(x=>x.id!==rec.id&&String(x.code||'').trim()===code);
    if(dup.length){
      setCat('⚠ Trong Khu vực thả đã có bản nháp cùng số thứ tự：#'+code+'「'+(dup[0].name||'Chưa đặt tên')+'」，Vui lòng đổi một số thứ tự khác');
    }
  }

