  function importWb(uidStr){
    const it=items.find(i=>String(i.uid)===String(uidStr));
    if(!it){setCat('Vui lòng chọn một vật phẩm Sách thế giới trước');return}
    const cn=(CATS.find(c=>c.id===it.categoryId)||{}).name||'';
    const o={id:uid(),target:String(it.uid)};
    o.name=it.title;o.cat=cn;
    o.keys=((it.entry&&it.entry.strategy&&it.entry.strategy.keys)||[]).join(', ');
    o.strategy=(it.entry&&it.entry.strategy&&it.entry.strategy.type==='constant')?'constant':'selective';
    o.order=String((it.entry&&it.entry.position&&it.entry.position.order)||100);
    o.subs=(it.submodes||[]).join('\n');
    o.desc=it.sections['Thông tin cơ bản']||'';o.mech=it.sections['Cơ chế & Cách dùng']||'';
    o.core=it.sections['Hiệu ứng cốt lõi']||'';o.scene=it.sections['Bối cảnh nhập vai']||'';o.safe=it.sections['Ghi đè an toàn']||'';
    o.code=String(it.code||'');
    db.lib[WB_TYPE]=db.lib[WB_TYPE].filter(x=>String(x.target)!==String(it.uid));
    db.lib[WB_TYPE].push(o);persistWb();renderWbSection();focusDropZone();
    setCat('✔ Đã đem #'+it.code+'「'+it.title+'」Nhập vào Khu vực thả (phương thức ghi đã đặt thành ghi đè mục này), có thể trực tiếp sửa đổi rồi cập nhật bằng một cú nhấp chuột; nhớ xóa thẻ này sau khi phát hành xong。');
  }
  async function wbAi(rec,mode,fk,idea){
    const def=TYPES[WB_TYPE];
    const label=(def.fields.find(f=>f[0]===fk)||['',fk])[1];
    const ideaTxt=String(idea||'').trim()||('（Người chơi không viết yêu cầu. Hãy đọc kỹ mục hiện tại và tự phán đoán '+(mode==='local'?('「'+label+'」Mục này'):'Toàn bộ mục')+' Những điểm cần tăng cường, sửa chữa hoặc làm nổi bật nhất, và viết lại dựa trên đó。）');
    const L=['Bạn sắp chỉnh sửa một mục đạo cụ trong Sách thế giới 《Mạng lười dâm khiếu》。','【Tên hiện tại】'+(rec.name||'Chưa đặt tên'),
      '【Từ khóa kích hoạt hiện tại】'+(rec.keys||'（Trống）'),'【Chế độ phụ hiện tại】'+(rec.subs||'（Trống）'),'【Mục đầy đủ hiện tại】'];
    def.fields.forEach(f=>{
      if(['name','cat','keys','subs','strategy','order','code'].indexOf(f[0])>=0)return;
      L.push(f[1]+':');
      L.push(String(rec[f[0]]||'（Trống）').split('\n').map(x=>'  '+x).join('\n'));
    });
    L.push('','【Yêu cầu chỉnh sửa】',ideaTxt,'');
    if(mode==='local'){
      L.push('【Chỉ cho phép sửa đổi】'+label);
      L.push('【Định dạng đầu ra】','===SECTION_START===','（Mới '+label+' Nội dung）','===SECTION_END===','【Yêu cầu】Các mục khác không được động dù chỉ một chữ; mục này viết lại hoàn toàn và giữ lại thông tin hợp lệ ban đầu。');
    }else{
      L.push('【Định dạng đầu ra】Xuất toàn bộ trường, không dùng code block, không giải thích：');
      def.fields.forEach(f=>{
        if(['cat','strategy','order','code'].indexOf(f[0])>=0)return;
        if(f[0]==='keys')L.push('Từ khóa kích hoạt: ...（3~8 cái, phân cách bằng dấu phẩy Trung Quốc hoặc dấu phẩy tiếng Anh, viết trên cùng một dòng）');
        else if(f[0]==='subs')L.push('Chế độ con: ...（3~8 cái, mỗi dòng một cái, mỗi cái 4~10 chữ）');
        else if(f[0]==='name')L.push('Tên đạo cụ: ...');
        else L.push(f[1]+': ...');
      });
      L.push('【Yêu cầu】Giữ nguyên những nội dung không bị yêu cầu thay đổi, chỉ sửa phần người chơi yêu cầu; tất cả các trường bắt buộc phải xuất ra, nghiêm cấm để trống; từ khóa kích hoạt và chế độ con phải tương ứng nghiêm ngặt với nội dung mục, không được viết thành câu giải thích。');
    }
    const rep=await callAI(L.join('\n'),'Bạn là trợ lý chỉnh sửa mục Sách thế giới 《Mạng lười dâm khiếu》, chỉ xuất văn bản có cấu trúc。');
    let text=String(rep||'').replace(/^```[a-zA-Z]*[ \t]*/gm,'').replace(/```$/gm,'').trim();
    if(mode==='local'){
      const m=text.match(/===SECTION_START===([\s\S]*?)===SECTION_END===/);
      let b=m?m[1].trim():text;
      if(/^（.*）$/.test(b))b='';
      if(!b)b=text;
      if(fk==='keys'){
        b=b.split('\n')[0].replace(/^(Từ khóa kích hoạt|Từ khóa)\s*[:：]\s*/,'');
        b=b.split(/[,，、]/).map(x=>x.trim()).filter(Boolean).join(', ');
      }
      if(fk==='subs'){
        b=String(b||'').split(/\n/).map(x=>x.replace(/^[-*•\d.、\s]+/,'').trim()).filter(Boolean).join('\n');
      }
      rec[fk]=b.replace(/^ {2}/gm,'');
    }else{
      const p=parseBlock(text,def.fields);
      def.fields.forEach(f=>{
        if(['cat','strategy','order','code'].indexOf(f[0])>=0)return;
        const v=String(p[f[0]]||'').trim();
        if(!v)return;
        if(f[0]==='keys')rec.keys=v.split(/\n/)[0].split(/[,，、]/).map(x=>x.trim()).filter(Boolean).join(', ');
        else if(f[0]==='subs')rec.subs=v.split(/\n/).map(x=>x.replace(/^[-*•\d.、\s]+/,'').trim()).filter(Boolean).join('\n');
        else rec[f[0]]=v;
      });
    }
    return rec;
  }
