  function injectCat(base,cn){
    if(!cn)return base;
    let b=String(base||'');
    const ln=b.match(/^[ \t]*Phân loại[ \t]*[:：][ \t]*(.*)$/m);
    if(ln){
      const rest=ln[1].replace(/[。.]$/,'').split(/[、，,]/).map(s=>s.trim()).filter(Boolean).filter(t=>t!==cn);
      b=b.replace(ln[0],'  Phân loại: '+[cn].concat(rest).join('、')+'。');
    }else b='  Danh mục: '+cn+'。'+(b?'\n'+b:'');
    return b;
  }
  function keyList(s,fb){
    const a=String(s||'').split(/[\n,，、;；]/).map(x=>x.trim()).filter(Boolean);
    if(a.length)return a;
    return Array.isArray(fb)?fb.filter(Boolean):[];
  }
  function subList(s){return String(s||'').split(/[\n,，、;；]/).map(x=>x.trim()).filter(Boolean).slice(0,12)}
  async function pushWb(){
    const h=P.TavernHelper;
    if(!h||!h.createWorldbookEntries){setCat('Trợ lý quán rượu không hỗ trợ tạo mục mới');return}
    if(!worldBook){setCat('Vui lòng đọc Sách thế giới trước（Nhấn góc trên bên phải ↻）');return}
    const list=lib(WB_TYPE).filter(r=>String(r.name||'').trim());
    if(!list.length){setCat('Khu vực thả chưa có vật phẩm: Nhấn trước「＋ Thêm đạo cụ mới」hoặc「📥 Nhập mục đã chọn」');return}
    let mx=Math.max.apply(null,[152].concat(items.map(i=>Number(i.code)||0)));
    const ups=[],crs=[],skp=[],subApp=[],catApp=[];
    const usedInBatch=new Set();
    list.forEach(rec=>{
      const nm=String(rec.name||'').trim();
      const vals={'Thông tin cơ bản':injectCat(rec.desc||'',rec.cat||'').trim(),'Cơ chế & Cách dùng':rec.mech||'','Hiệu ứng cốt lõi':rec.core||'','Bối cảnh nhập vai':rec.scene||'','Ghi đè an toàn':rec.safe||''};
      const st=rec.strategy==='constant'?'constant':'selective';
      const od=Number(rec.order)||100;
      if(rec.target){
        const hit=items.find(i=>String(i.uid)===String(rec.target));
        if(hit){
          const wantC=String(rec.code||'').trim();
          const code=(/^\d{1,4}$/.test(wantC)?wantC.padStart(3,'0'):(hit.code||String(++mx).padStart(3,'0'))).padStart(3,'0');
          const ok=(hit.entry&&hit.entry.strategy&&hit.entry.strategy.keys)||[hit.title];
          ups.push({uid:hit.uid,name:code+'. '+nm,content:buildYaml(code,nm,vals),keys:keyList(rec.keys,ok),st,od});
          subApp.push({code,subs:subList(rec.subs)});
          catApp.push({code,catId:catIdByName(rec.cat)});
          return;
        }
      }
      if(items.some(i=>i.title===nm)){skp.push(nm);return}
      let next='';
      const wantN=String(rec.code||'').trim();
      if(/^\d{1,4}$/.test(wantN)){
        const c3=wantN.padStart(3,'0');
        if(items.some(i=>String(i.code)===c3)){skp.push(nm+'(Số thứ tự#'+c3+' Đã sử dụng)');return}
        if(usedInBatch.has(c3)){skp.push(nm+'(Số thứ tự#'+c3+' Lặp lại trong đợt này)');return}
        usedInBatch.add(c3);next=c3;mx=Math.max(mx,Number(c3));
      }else{
        next=String(++mx).padStart(3,'0');
        while(usedInBatch.has(next))next=String(++mx).padStart(3,'0');
        usedInBatch.add(next);
      }
      crs.push({name:next+'. '+nm,content:buildYaml(next,nm,vals),strategy:{type:st,keys:keyList(rec.keys,[nm])},position:{type:'after_character_definition',order:od},enabled:true});
      subApp.push({code:next,subs:subList(rec.subs)});
      catApp.push({code:next,catId:catIdByName(rec.cat)});
    });
    if(!ups.length&&!crs.length){setCat('Đạo cụ trong Khu vực thả đều đã tồn tại trong Sách thế giới, không cần ghi lại lần nữa（Tổng '+skp.length+' mục）');return}
    setCat('Đang ghi: Ghi đè '+ups.length+' mục / Tạo mới '+crs.length+' mục…');
    try{
      let wb=allEntries;
      if(ups.length){
        wb=await h.updateWorldbookWith(worldBook,src=>src.map(e=>{
          const u=ups.find(x=>String(x.uid)===String(e.uid));
          if(!u)return e;
          return Object.assign({},e,{name:u.name,comment:u.name,content:u.content,
            strategy:Object.assign({},e.strategy||{},{type:u.st,keys:u.keys}),
            position:Object.assign({},e.position||{},{order:u.od})});
        }));
      }
      if(crs.length){const res=await h.createWorldbookEntries(worldBook,crs);wb=res.worldbook||wb}
      if(Array.isArray(wb))allEntries=wb;
      subApp.forEach(x=>{if(x.subs.length)SUBOV[x.code]=x.subs;else delete SUBOV[x.code]});
      saveSubOv();
      catApp.forEach(x=>{if(x.catId)CATOV[x.code]=x.catId});
      saveCatOv();
      items=allEntries.map(parseEntry);
      if(selected)selected=items.find(i=>i.uid===selected.uid)||selected;
      renderList();
      await updateCatalogs(true);
      const msg='✔ Ghi đè '+ups.length+' mục / Tạo mới '+crs.length+' mục, đã ghi vào Sách thế giới và cập nhật mục lục'+(skp.length?'（Bỏ qua trùng tên '+skp.length+' mục）':'')+'。Nhớ xóa các mục đã đăng trong Khu vực thả。';
      setCat(msg);setSt(msg);
    }catch(e){setCat('✘ Ghi vào Sách thế giới thất bại：'+(e&&e.message?e.message:e))}
  }

