 {kind:'Nguyên tố',name:'【Hắc Thực Cuồng Long】',desc:'Khi bị đối xử thô bạo cùng làm nhục, dopamine tăng vọt theo cấp số nhân, khắc sâu cảm giác “bị áp chế cưỡng bức” thành phần thưởng duy nhất'},
 {kind:'Nguyên tố',name:'【Dung nham Viêm Tủy】',desc:'Khi cực khoái, trong khoang tiết ra chất dịch nhiệt độ cao trong thời gian ngắn, khiến bên thâm nhập trải nghiệm cảm giác bao bọc nóng bỏng gần như bỏng rát'},
 {kind:'Nguyên tố',name:'【Thủy triều thấm đẫm】',desc:'Lượng dịch tiết tăng theo chỉ số cảm xúc, khi được khen ngợi thì tràn trề như lũ, khi bị lạnh nhạt thì khô hạn khó nhịn'}
];

/* ===== Bể thẻ（bốn phẩm chất, không định sẵn lá bài cụ thể） ===== */
const CARD_QUALITIES=[
 {q:'Lục',tag:'Cơ bản',desc:'Thẻ hành động cơ bản: những chiêu khởi đầu như thâm nhập, quan hệ bằng miệng, liếm láp, vuốt ve, khoái cảm có hạn nhưng tiêu hao cực thấp'},
 {q:'Lam',tag:'Tinh thông',desc:'Thẻ động tác tinh thông: các thủ thuật kỹ thuật như đóng cọc điểm yếu, kỹ thuật lưỡi dài, nhịp điệu cưỡi ngựa, tiêu hao trung bình mang lại hồi đáp cao'},
 {q:'Tím',tag:'Tuyệt kỹ',desc:'Thẻ tuyệt kỹ: Các kỹ năng cường độ cao như súng máy nhiệt long sâu cổ họng, gương phản chiếu cảm quan kép, hút chân không xoáy nước, cái giá phải trả là thể lực tụt dốc không phanh'},
 {q:'Vàng',tag:'Kết liễu',desc:'Thẻ chiêu thức tối thượng: Rót dung nham áp suất cao, vắt chân không xoay tròn siêu áp cự ly gần, một đòn định thắng bại nhưng chỉ dùng được một lần'}
];

const roll=a=>a[Math.floor(Math.random()*a.length)];
  let curCard=null;

  /* ===== Danh sách thả xuống ===== */
  let gTags=[],gbTags=[],ggTags=[],glTags=[],gcTags=[],tagQ='',gbTagQ='',ggTagQ='',glTagQ='',gcTagQ='';
  function fillSel(sel,items,valKey,labelFn){
    if(!sel)return;const cur=sel.value;sel.replaceChildren();
    if(sel.classList&&(sel.classList.contains('gb-role')||sel.classList.contains('gb-id')||sel.classList.contains('gb-world'))){
      const n=el('option','','none（Không đổi, giữ nguyên chủ thể）');n.value='none';sel.append(n);
    }
    items.forEach(x=>{
      const v=valKey?x[valKey]:x;
      const lb=labelFn?labelFn(x):(valKey?String(x[valKey]):String(x));
      const o=el('option','',lb);o.value=v;sel.append(o);
    });
    if(cur&&Array.from(sel.options).some(o=>o.value===cur))sel.value=cur;
  }
  function renderGenePool(){
    const kind=$('.gg-kind')?$('.gg-kind').value:'Thể xác';
    const pool=GENE_POOL.filter(g=>g.kind===kind);
    fillSel($('.gg-gene'),pool,'name',g=>g.name+'· '+g.desc.slice(0,20)+'…');
  }
  function renderCardQuality(){
    const q=$('.gl-q')?$('.gl-q').value:'Lục';
    const d=CARD_QUALITIES.find(x=>x.q===q);
    const inp=$('.gl-qdesc');if(inp)inp.value=d?(d.q+'｜'+d.tag+'：'+d.desc):'';
  }
  function fillPools(){
    fillSel($('.gb-role'),MR);
    fillSel($('.gb-id'),MI);
    fillSel($('.gb-world'),MW);
    const ks=$('.gg-kind');
    if(ks&&!ks.children.length){GENE_KINDS.forEach(k=>{const o=el('option','',k);o.value=k;ks.append(o)})}
    const qs=$('.gl-q');
    if(qs&&!qs.children.length){CARD_QUALITIES.forEach(c=>{const o=el('option','',c.q+'｜'+c.tag);o.value=c.q;qs.append(o)})}
    renderGenePool();renderCardQuality();
    renderTkTargets();syncRarityHint();
    buildRwTypes();renderRwForm();
  }
  function renderTkTargets(){
    $$('.tk-target').forEach(s=>{
      const cur=s.value;s.replaceChildren();
      if(!db.targets.length){const o=el('option','','（Chưa có mục tiêu, hãy tạo hồ sơ ở trang 【Mục tiêu】trước）');o.value='';s.append(o);return}
      db.targets.forEach(t=>{const o=el('option','',t.name);o.value=t.id;s.append(o)});
      if(cur&&db.targets.some(t=>t.id===cur))s.value=cur;
    });
  }
  const renderGbTargets=renderTkTargets;
  const setG=(m,sel)=>{try{const e=$(sel);if(e)e.textContent=m||''}catch(_){}};

  /* ===== TAG Bể（Bể vật hóa được cách ly nghiêm ngặt với các bể thông thường） ===== */
  function tagGroupsFor(tk){
    if(tk==='chains')return [{id:'chain',name:'Chuyên dụng vật hóa（Nội thất nhân thể / Bồn cầu / Phương tiện）',tags:CHAIN_TAGS}];
    if(tk==='crowns')return CROWN_TAGS;
    if(tk==='beasts')return BEAST_TAGS;
    if(tk==='swarms')return SWARM_TAGS;
    return TAG_GROUPS;
  }
  const TAG_CAP=36,TAG_CAP_Q=240,TAG_CAP_ALL=1500;
  const TGX_KEY='yj_sv7_tgexpand';
  let tgExpand={g:{},b:{},r:{},gg:{},gl:{},gc:{},gbr:{},gbi:{},gbw:{}};
  try{const v=JSON.parse(localStorage.getItem(TGX_KEY)||'null');if(v&&typeof v==='object')Object.keys(tgExpand).forEach(k=>{if(v[k]&&typeof v[k]==='object')tgExpand[k]=v[k]})}catch(_){}
  const saveTgExpand=()=>{try{localStorage.setItem(TGX_KEY,JSON.stringify(tgExpand))}catch(_){}};
  function storeOf(kind){
    return kind==='g'?gTags:kind==='b'?gbTags:kind==='r'?rwTags:kind==='gg'?ggTags:kind==='gc'?gcTags:kind==='gbr'?gbrTags:kind==='gbi'?gbiTags:kind==='gbw'?gbwTags:glTags;
  }
  function tagCount(kind,groups,q){
    const qq=String(q||'').trim().toLowerCase();
    let n=0;
    groups.forEach(g=>{n+=g.tags.filter(t=>!qq||String(t).toLowerCase().indexOf(qq)>=0).length});
    return n;
  }
  function renderTagsInto(box,groups,kind,q,counterSel,redraw,afterToggle){
    const store=storeOf(kind);
    box.replaceChildren();
    const setCnt=()=>{const c=counterSel?$(counterSel):null;if(c)c.textContent='Đã chọn '+storeOf(kind).length};
    setCnt();
    if(!groups.length){box.append(el('div','tagempty','Chưa bật bất kỳ danh mục nào —— nhấn vào danh mục ở trên để mở'));return}
    const qq=String(q||'').trim().toLowerCase();
    const cap=qq?TAG_CAP_Q:TAG_CAP;
    let total=0;
    groups.forEach(g=>{
      const hits=g.tags.filter(t=>!qq||String(t).toLowerCase().indexOf(qq)>=0);
      if(!hits.length)return;
      total+=hits.length;
      const opened=!!(tgExpand[kind]&&tgExpand[kind][g.id]);
      const cap2=qq?TAG_CAP_Q:(opened?TAG_CAP_ALL:TAG_CAP);
      const pick=hits.slice(0,cap2);
      const hb=el('button','tgh tgh-btn'+(opened?' open':''),
        (opened?'▾ ':'▸ ')+g.name+' · '+hits.length+(opened?'（Đã mở rộng tất cả）':(hits.length>pick.length?'（Nhấn để xem tất cả '+hits.length+' mục）':'')));
      hb.type='button';hb.dataset.gid=g.id;
      hb.title=opened?'Nhấn để thu gọn phân loại này':'Nhấn để xem tất cả mục trong danh mục này TAG';
      box.append(hb);
      pick.forEach(t=>{
        const b=el('button','tg'+(store.indexOf(t)>=0?' on':''),t);
        b.type='button';b.dataset.tag=t;
        box.append(b);
      });
    });
    if(!total)box.append(el('div','tagempty','Không có kết quả khớp TAG'));
    setCnt();
    if(!box.dataset.bound){
      box.dataset.bound='1';
      box.addEventListener('click',e=>{
        const h=e.target.closest('.tgh-btn');
        if(h&&box.contains(h)){
          const gid=h.dataset.gid;
          if(!tgExpand[kind])tgExpand[kind]={};
          tgExpand[kind][gid]=!tgExpand[kind][gid];
          saveTgExpand();
          if(typeof redraw==='function'){redraw();return}
          renderAllTagPools();return;
        }
        const b=e.target.closest('.tg');if(!b||!box.contains(b))return;
        const t=b.dataset.tag;
        const arr=storeOf(kind);
        const i=arr.indexOf(t);
        if(i>=0)arr.splice(i,1);else arr.push(t);
        b.classList.toggle('on',i<0);
        const c=counterSel?$(counterSel):null;if(c)c.textContent='Đã chọn '+arr.length;
        if(typeof afterToggle==='function'){try{afterToggle(t,i>=0,arr)}catch(_){}}
      });
    }
  }
  const TG_KEY='yj_sv5_tagscope';
  const tgScope={g:null,b:null,r:null,gg:null,gl:null,gc:null,gbr:null,gbi:null,gbw:null};
  function loadScopes(){
    try{
      const v=JSON.parse(localStorage.getItem(TG_KEY)||'null');
      if(v&&typeof v==='object'){
        ['g','b','r','gg','gl','gc','gbr','gbi','gbw'].forEach(k=>{if(Array.isArray(v[k]))tgScope[k]=new Set(v[k])});
      }
    }catch(_){}
  }
  function saveScopes(){
    try{localStorage.setItem(TG_KEY,JSON.stringify({g:tgScope.g?[...tgScope.g]:null,b:tgScope.b?[...tgScope.b]:null,r:tgScope.r?[...tgScope.r]:null,gg:tgScope.gg?[...tgScope.gg]:null,gl:tgScope.gl?[...tgScope.gl]:null}))}catch(_){}
  }
  function activeGroups(kind,groups){
    const sc=tgScope[kind];
    if(!sc)return groups;
    return groups.filter(g=>sc.has(g.id));
  }
  function renderScopeFilters(box,kind,groups){
    if(!box)return;
    box.replaceChildren();
    box.append(el('span','tghint','Phạm vi rút：'));
    groups.forEach(g=>{
      const on=!tgScope[kind]||tgScope[kind].has(g.id);
      const b=el('button','tgf'+(on?' on':' off'),g.name);b.type='button';
      b.title=on?'Nhấn để đóng phân loại này':'Nhấn để mở phân loại này';
      b.addEventListener('click',()=>{
        if(!tgScope[kind])tgScope[kind]=new Set(groups.map(x=>x.id));
        const s=tgScope[kind];
        if(s.has(g.id))s.delete(g.id);else s.add(g.id);
        saveScopes();renderAllTagPools();
      });
      box.append(b);
    });
    const all=el('button','tgf on','Bật hết');all.type='button';all.title='Bật tất cả phân loại';
    all.addEventListener('click',()=>{tgScope[kind]=null;saveScopes();renderAllTagPools()});
    const none=el('button','tgf off','Tắt hết');none.type='button';
    none.title='Đóng toàn bộ phân loại, rồi mở từng cái cần thiết';
    none.addEventListener('click',()=>{tgScope[kind]=new Set();saveScopes();renderAllTagPools()});
    box.append(all,none);
  }
  function renderAllTagPools(){renderTagPool();renderGbTagPool();renderRwTagPool();renderGgTagPool();renderGlTagPool();renderGcTagPool()}
  function gcGroups(){
    const b=$('.gc-branch')?$('.gc-branch').value:'auto';
    if(b==='Thần bị')return [CROWN_TAGS[0]];
    if(b==='Vặn vẹo')return [CROWN_TAGS[1]];
    return CROWN_TAGS;
  }
  function renderGcTagPool(){
    const box=$('.gc-tagpool');if(!box)return;
    const gs=gcGroups();
    renderScopeFilters($('.gc-tgfilters'),'gc',gs);
    renderTagsInto(box,activeGroups('gc',gs),'gc',gcTagQ,'.gc-tgselcnt',renderGcTagPool);
  }
  function renderTagPool(){
    const box=$('.tagpool');if(!box)return;
    const tk=$('.wstype')?$('.wstype').value:'';
    const all=tagGroupsFor(tk);
    renderScopeFilters($('.tgfilters'),'g',all);
    renderTagsInto(box,activeGroups('g',all),'g',tagQ,'.tgselcnt',renderTagPool);
  }
  const GB_KIND={role:'gbr',id:'gbi',world:'gbw'};
  const GB_POOLS={
    gbr:{box:'.gb-role-tagpool',flt:'.gb-role-filters',slot:'role',ids:['rel','role']},
    gbi:{box:'.gb-id-tagpool',flt:'.gb-id-filters',slot:'id',ids:['role','look']},
    gbw:{box:'.gb-world-tagpool',flt:'.gb-world-filters',slot:'world',ids:['plot','place']}
  };
  let gbrTags=[],gbiTags=[],gbwTags=[];
  let gbPoolQ={gbr:'',gbi:'',gbw:''};
  function writeGbTag(slot,t,removed){
    try{
      const inp=$('.gb-'+slot+'-filter');
      if(!inp)return;
      if(removed){
        const parts=String(inp.value||'').split(/[；;]/).map(x=>x.trim()).filter(Boolean).filter(x=>x!==t);
        inp.value=parts.join('；');
      }else{
        const cur=String(inp.value||'').trim();
        if(cur.indexOf(t)>=0)return;
        inp.value=cur?(cur+'；'+t):t;
      }
      syncRarityHint();
      setG('🏷 「'+t+'」Đã '+(removed?'Chuyển ra':'Ghi vào')+' '+({role:'① Khuynh hướng nhân vật',id:'② Bước nhảy thân phận',world:'③ Tuyến thế giới'}[slot]||slot),'.gb-st');
    }catch(_){}
  }
  function renderGbPool(kind){
    try{
      const cfg=GB_POOLS[kind];if(!cfg)return;
      const box=$(cfg.box);if(!box)return;
      const gs=TAG_GROUPS;
      renderScopeFilters($(cfg.flt),kind,gs);
      const det=box.closest('details');
      if(det&&!det.open){
        box.replaceChildren(el('div','tagempty','Mở rộng tiêu đề phía trên để tải toàn bộ từ vựng'));
        return;
      }
      renderTagsInto(box,activeGroups(kind,gs),kind,gbPoolQ[kind],null,()=>renderGbPool(kind),(t,rm)=>writeGbTag(cfg.slot,t,rm));
    }catch(_){}
  }
  function renderGbTagPool(){renderGbPool('gbr');renderGbPool('gbi');renderGbPool('gbw')}

  function renderRwTagPool(){
    const box=$('.rw-tagpool');if(!box)return;
    renderScopeFilters($('.rw-tgfilters'),'r',TAG_GROUPS);
    renderTagsInto(box,activeGroups('r',TAG_GROUPS),'r',rwTagQ,'.rw-tgselcnt',renderRwTagPool);
  }
  function renderGgTagPool(){
    const box=$('.gg-tagpool');if(!box)return;
    renderScopeFilters($('.gg-tgfilters'),'gg',GENE_TAGS);
    renderTagsInto(box,activeGroups('gg',GENE_TAGS),'gg',ggTagQ,'.gg-tgselcnt',renderGgTagPool);
  }
  function renderGlTagPool(){
    const box=$('.gl-tagpool');if(!box)return;
    renderScopeFilters($('.gl-tgfilters'),'gl',CARD_TAGS);
    renderTagsInto(box,activeGroups('gl',CARD_TAGS),'gl',glTagQ,'.gl-tgselcnt',renderGlTagPool);
  }

  /* ===== Liên kết số đèn（Số đèn quyết định ô: Tùy chọn / Từ khóa lọc định hướng / Nhấp chọn TAG，Bất kỳ cái nào cũng tính là đã động vào ô này） ===== */
  const GB_COLS=[
    {no:'①',label:'Khuynh hướng nhân vật',sel:'.gb-role', flt:'.gb-role-filter', tags:()=>gbrTags},
    {no:'②',label:'Bước nhảy thân phận',sel:'.gb-id',   flt:'.gb-id-filter',   tags:()=>gbiTags},
    {no:'③',label:'Tuyến thế giới',  sel:'.gb-world',flt:'.gb-world-filter',tags:()=>gbwTags}
  ];
  function gbColWhy(col){
    const why=[];
    const s=$(col.sel);
    if(s&&String(s.value||'none')!=='none')why.push('Tùy chọn');
    const f=$(col.flt);
    if(f&&String(f.value||'').trim())why.push('Từ định hướng');
    const arr=col.tags();
    if(arr&&arr.length)why.push('TAG');
    return why;
  }
  const RAR_COL={1:['Khuynh hướng nhân vật'],2:['Khuynh hướng nhân vật','Bước nhảy thân phận'],3:['Khuynh hướng nhân vật','Bước nhảy thân phận','Cải biên dòng thời gian']};
  let lastRar=1;
  function setRarity(n){
    const hid=$('.gb-rar');if(hid)hid.value=String(Math.max(1,Math.min(3,Number(n)||1)));
    syncRarityHint();
  }
  function effRarity(){
    let n=0;
    GB_COLS.forEach(c=>{if(gbColWhy(c).length)n++});
    return Math.max(1,Math.min(3,n));
  }
  function syncRarityHint(){
    const eff=effRarity();
    const hid=$('.gb-rar');if(hid)hid.value=String(eff);
    const view=$('.gb-rar-view');if(view)view.value=thLamp(eff)+'　'+eff+' Đèn';
    const parts=[];
    GB_COLS.forEach(c=>{const why=gbColWhy(c);if(why.length)parts.push(c.no+' '+c.label+'（'+why.join('＋')+'）')});
    const hint=$('.gb-lock');
    if(hint)hint.textContent=parts.length
      ?('Mục thay đổi：'+parts.join(' / ')+'　→　'+thLamp(eff)+' '+eff+' Đèn（Các cột chưa thay đổi giữ nguyên chủ sở hữu cũ）')
      :'Cả ba cột đều chưa động: menu thả xuống toàn là none、Lọc định hướng để trống, cũng chưa bấm TAG。Khai thác ra như vậy mới chính là bản thân nguyên chủ, ít nhất phải chỉnh sửa một cột thì mới có ý nghĩa của 「đồng vị thể」';
  }
  function bumpRarity(){syncRarityHint()}

  /* ===== Xúc xắc: nút riêng, chỉ thay đổi cột mục tiêu, không ảnh hưởng đến các cột khác ===== */
  function rollRole(){ $('.gb-role').value=roll(MR); bumpRarity(); setG('🎲 Khuynh hướng nhân vật đã được quay lại','.gb-st'); }
  function rollId(){ $('.gb-id').value=roll(MI); bumpRarity(); setG('🎲 Bước nhảy thân phận đã được quay lại（Tự động nâng lên đèn hai）','.gb-st'); }
  function rollWorld(){ $('.gb-world').value=roll(MW); bumpRarity(); setG('🎲 Tuyến thế giới chỉnh sửa lớn đã được quay lại（Tự động nâng lên ba đèn）','.gb-st'); }
  function rollGene(){
    const kind=$('.gg-kind').value;
    const pool=GENE_POOL.filter(g=>g.kind===kind);
    const g=roll(pool);
    $('.gg-gene').value=g.name;
    setG('🎲 Ví dụ đã đổi thành【'+g.kind+'】'+g.name+'（AI Sẽ viết thêm một mục mới dựa trên đây）','.gg-st');
  }
  function rollCardQ(){
    const c=roll(CARD_QUALITIES);
    $('.gl-q').value=c.q;renderCardQuality();
    setG('🎲 Phẩm chất đã đổi thành '+c.q+'｜'+c.tag+'（AI Sẽ dựa vào đây để viết riêng chiêu thức mới）','.gl-st');
  }
  function rollAllByRarity(){
    const eff=effRarity();
    $('.gb-role').value=roll(MR);
    if(eff>=2)$('.gb-id').value=roll(MI);
    if(eff>=3)$('.gb-world').value=roll(MW);
    syncRarityHint();
    setG('🎲 Đã nhấn '+eff+' đèn quay ra '+(RAR_COL[eff]||[]).length+' ô','.gb-st');
  }

  function pickSignal(){
    const rar=effRarity();
    const gv=s=>{const e=$(s);const v=e?String(e.value||'none'):'none';return v==='none'?'':v};
    const gf=s=>{const e=$(s);return e?String(e.value||'').trim():''};
    const changed=[];
    GB_COLS.forEach(c=>{const why=gbColWhy(c);if(why.length)changed.push(c.no+' '+c.label+'（'+why.join('＋')+'）')});
    return {
      rar:rar,
      role:gv('.gb-role'),id:gv('.gb-id'),wd:gv('.gb-world'),
      rf:gf('.gb-role-filter'),idf:gf('.gb-id-filter'),wdf:gf('.gb-world-filter'),
      changed:changed
    };
  }

  /* ===== Lời nhắc（Bao gồm quy định số từ cứng nhắc） ===== */
