  async function drawCard(kind){
    const M={personas:['.gb-target','.gb-draw','.gb-st'],genes:['.gg-target','.gg-draw','.gg-st'],cards:['.gl-target','.gl-draw','.gl-st']};
    const tS=M[kind][0],bS=M[kind][1],sS=M[kind][2];
    const t=db.targets.find(x=>x.id===$(tS).value);
    if(!t){setG('✘ Vui lòng tạo nhân vật mới ở trang【Mục tiêu】trước',sS);return}
    let sig;
    if(kind==='personas')sig=pickSignal();
    else if(kind==='genes'){
      const kd=$('.gg-kind').value||'Thể xác';
      const gp=GENE_POOL.filter(g=>g.kind===kd);
      const nm=$('.gg-gene').value;
      sig={gene:gp.find(g=>g.name===nm)||roll(gp)};
    }else{
      sig={q:$('.gl-q').value||'Lục'};
    }
    const custom=kind==='personas'?'':(kind==='genes'?$('.gg-custom').value.trim():$('.gl-custom').value.trim());
    const btn=$(bS);btn.disabled=true;const old=btn.textContent;btn.textContent='⏳ Đang tính toán…';
    setG('⏳ Đang tìm kiếm các vũ trụ song song…',sS);
    try{
      const rep=await callAI(buildPrompt(kind,sig,custom),api.sysPrompt||SYS_PROMPT);
      const def=TYPES[kind];
      const arr=parseBlocks(rep,def.fields);
      if(!arr.length)throw new Error('Không phân tích được dữ liệu, vui lòng đổi interface khác thử lại');
      const rec={id:uid()};
      def.fields.forEach(f=>rec[f[0]]=String(arr[0][f[0]]||'').trim());
      if(kind==='personas'){rec.rarity=String(sig.rar);rec.loaded=''}
      curCard={rec:rec,kind:kind,targetId:t.id,targetName:t.name};
      renderCrt(rec,kind);
      let ok='✔ Tạo thành công, vui lòng xác nhận trước khi lưu trữ';
      if(kind==='personas'){
        const seg=String(rec.name||'').split(/[·・\-—–|｜／\/]/)[0].trim();
        if(seg&&seg.length<2)ok='⚠ Đã tạo, nhưng tên thẻ chỉ bắt đầu bằng「'+seg+'」một chữ. Ô tên phải viết tên đầy đủ (Faust không được viết thành F), bấm tạo lại một lần là thường sẽ chuẩn';
      }
      setG(ok,sS);
    }catch(e){setG('✘ Thất bại：'+(e&&e.message?e.message:e),sS)}
    finally{btn.disabled=false;btn.textContent=old}
  }
  function renderCrt(rec,kind){
    const w=$('.crt');w.hidden=false;
    const def=TYPES[kind];
    w.querySelector('.cname').textContent=rec.name||'Hồ sơ chưa rõ';
    if(kind==='personas'){w.querySelector('.crar').textContent=thLamp(rec.rarity);w.querySelector('.ccon').textContent=rec.concept||''}
    else if(kind==='genes'){w.querySelector('.crar').textContent='🧬';w.querySelector('.ccon').textContent=(rec.look||'')+'｜'+def.label}
    else if(kind==='crowns'){w.querySelector('.crar').textContent=String(rec.cat||'❄').slice(0,1);w.querySelector('.ccon').textContent=(rec.concept||rec.look||'')+'｜'+def.label}
    else{w.querySelector('.crar').textContent=String(rec.look||'◆').slice(0,1);w.querySelector('.ccon').textContent=(rec.look||'')+'｜'+def.label}
    const bi=w.querySelector('.cbi');bi.replaceChildren();
    def.fields.forEach(f=>{
      if(['name','rarity','concept'].indexOf(f[0])>=0)return;
      const r=el('div','');
      r.append(el('b','','【'+f[1]+'】'),D.createTextNode(rec[f[0]]||'—'));
      bi.append(r);
    });
    const na=w.querySelector('.cna');na.replaceChildren();
    na.append(el('div','chitem','Mục tiêu：'+(curCard?curCard.targetName:'—')));
    na.append(el('div','chitem','Loại：'+def.label+'　Số trường：'+def.fields.length));
  }
  function archiveCard(load){
    if(!curCard)return;
    const t=db.targets.find(x=>x.id===curCard.targetId);
    if(!t)return;
    const def=TYPES[curCard.kind];
    const clone={id:uid()};
    def.fields.forEach(f=>clone[f[0]]=curCard.rec[f[0]]||'');
    if(curCard.kind==='personas')clone.loaded=load?'1':'';
    db.lib[curCard.kind].push(clone);
    att(t,curCard.kind,clone.id);
    saveDb();renderTDetail();renderRecords();
    $('.crt').hidden=true;
    const nm=clone.name||'Chưa đặt tên';
    if(load){
      let txt;
      if(curCard.kind==='personas')txt='*'+U+' Đem「'+nm+'」Lá bài cắm vào khe thẻ phía trên súng điều khiển, bóp cò cùng hiệu ứng âm thanh chói tai 「Điều khiển hình thái! Ghi đè nhân cách!」 —— dòng lũ dữ liệu hologram 3D phun trào, ghi đè lên '+t.name+' trang phục và cấu tạo thể xác. Ý thức thực tại của cô ấy bị đẩy vào phòng cách ly an toàn, nhân cách dị giới chính thức tiếp quản cơ thể này。*';
      else if(curCard.kind==='genes')txt='*'+U+' Đem「'+nm+'」Kéo thả chuỗi gen '+t.name+' bảng chỉnh sửa Đá Truyền Thừa của, đầu ngón tay hạ xuống nút 「Nạp」 —— cùng âm thanh hệ thống trong trẻo, bảng hologram màu vàng hiện lên dòng chữ 【Trạng thái đã kích hoạt】, cơ thể cô ấy trong cơn run rẩy đã bị ghi vĩnh viễn đặc tính sinh thái ma vật này。*';
      else txt='*'+U+' Đem「'+nm+'」Rút ra rồi đập mạnh lên bàn quyết đấu ở tầng tiếp tân, thẻ bài hóa thành mệnh lệnh hành vi thể xác tuyệt đối nhắm thẳng vào '+t.name+'——Cô phải chịu đựng toàn bộ khoái cảm và tiêu hao thể lực của lá bài này trong thời gian cực ngắn。*';
      fillInput(txt);
    }
    curCard=null;
  }
  function sendStory(kind){
    const M={personas:['.gb-target','.gb-role-filter'],genes:['.gg-target','.gg-custom'],cards:['.gl-target','.gl-custom']};
    const t=db.targets.find(x=>x.id===$(M[kind][0]).value);
    const nm=t?t.name:'Mục tiêu';
    const custom=$(M[kind][1]).value.trim();
    let txt;
    if(kind==='personas'){
