  /* ===== Đồng bộ ===== */
  function getUserName(){
    const s=apiFn('substituteParams');
    if(s){try{const v=s('{{user}}');if(v&&String(v).indexOf('{{')<0)return String(v).trim()}catch(_){}}
    const c=stCtx();if(c&&c.name1)return String(c.name1).trim();
    return '';
  }
  function isMe(nm){
    const n=String(nm||'').trim();if(!n)return true;
    const l=n.toLowerCase();
    if(['user','Tôi','Bạn','Nhân vật chính','Người chơi','Người dùng','{{user}}'].indexOf(l)>=0)return true;
    const real=getUserName();
    if(real&&(l===real.toLowerCase()||n===real))return true;
    if(db.user.name&&n===db.user.name)return true;
    return false;
  }
  function recentText(n){
    const g=apiFn('getChatMessages'),gl=apiFn('getLastMessageId');
    if(!g||!gl)return '';
    try{
      const last=gl();if(last==null)return '';
      const list=g(Math.max(0,last-(n||3)+1)+'-'+last)||[];
      return list.map(m=>String(m.message||m.mes||'').replace(/<tse_meta[\s\S]*?<\/tse_meta>/gi,'').trim()).filter(Boolean).join('\n\n');
    }catch(_){return ''}
  }
  function newTarget(nm){
    const t={id:uid(),name:nm||'Nhân vật chưa đặt tên',note:'',status:'',counters:{},parts:{},items:[],refs:emptyRefs(),updatedAt:''};
    COUNTERS.forEach(d=>t.counters[d.key]=0);
    PARTS.forEach(d=>t.parts[d.key]={lv:0,note:''});
    return t;
  }
  async function syncAll(){
    const chat=recentText(4);
    if(!chat){$('.tline').textContent='✘ Không lấy được nội dung gần nhất, hãy có lịch sử trò chuyện trước';return}
    const btn=$('.sync-all'),tb=$('.tsync');
    btn.disabled=true;tb.disabled=true;
    $('.tline').textContent='⏳ Đang phân tích các tầng gần đây…';
    try{
      const L=['【Hồ sơ nhân vật hiện có】'];
      if(!db.targets.length)L.push('（Không có）');
      db.targets.forEach(t=>L.push('<<'+t.name+'>> Thân phận：'+(t.note||'Chưa rõ')+'；Trạng thái：'+(t.status||'Không')));
      L.push('','【Nội dung chính gần đây】',chat,'');
      L.push('【Nhiệm vụ】Lấy nội dung chính văn mới nhất làm chuẩn, xuất hồ sơ toàn bộ nhân vật nữ quan trọng xuất hiện trong lượt này。');
      L.push('【Tuyệt đối cấm】Đừng đem「'+(getUserName()||'user')+'」hoặc chính người chơi được xuất như nhân vật。');
      L.push('Định dạng đầu ra：','===ENTRY_START===','Họ tên: ','Thân phận: ','Trạng thái: ','===ENTRY_END===','【Yêu cầu】Nghiêm cấm để trống bất kỳ trường nào。');
      const rep=await callAI(L.join('\n'),api.sysPrompt||SYS_PROMPT);
      const blocks=parseBlocks(rep,[['name','Họ tên'],['note','Thân phận'],['status','Trạng thái']]);
      if(!blocks.length)throw new Error('Chưa phân tích được dòng nhân vật');
      let cr=0,sk=0;const now=new Date().toLocaleString('zh-CN',{hour12:false});
      blocks.forEach(b=>{
        const nm=String(b.name||'').trim();
        if(!nm)return;
        if(isMe(nm)){sk++;return}
        let t=db.targets.find(x=>x.name===nm);
        if(!t){t=newTarget(nm);db.targets.push(t);cr++}
        if(b.note)t.note=String(b.note).trim();
        if(b.status)t.status=String(b.status).trim();
        t.updatedAt=now;
      });
      saveDb();renderTList();renderTDetail();renderGbTargets();
      $('.tline').textContent='✔ Đồng bộ '+(blocks.length-sk)+' nhân vật'+(cr?'，Tạo mới '+cr+' Tên':'')+(sk?'，Đã bỏ qua '+sk+' Mục người chơi':'');
      if(page==='records')renderRecords();
    }catch(e){$('.tline').textContent='✘ Đồng bộ thất bại：'+(e&&e.message?e.message:e)}
    finally{btn.disabled=false;tb.disabled=false}
  }
