  $('.uitheme').addEventListener('click',e=>{const b=e.target.closest('.uith');if(b&&b.dataset.th)setTheme(b.dataset.th)});
  $('.uifs').addEventListener('change',()=>{ui.fontSize=Number($('.uifs').value)||14;applyUi();try{localStorage.setItem(UI_KEY,JSON.stringify(ui))}catch(_){}});

  /* ===== Kéo thả ===== */
  let drag=false,moved=false,pid=null,sx=0,sy=0,L=0,T=0,bL=0,bT=0;
  function initPos(){
    const vw=P.innerWidth||380,vh=P.innerHeight||680,mob=vw<=768;
    L=mob?vw-68:44;T=mob?vh-132:160;
    try{
      const s=JSON.parse(localStorage.getItem(POS_KEY)||'null');
      if(s&&isFinite(parseFloat(s.left))&&isFinite(parseFloat(s.top))){
        L=Math.max(6,Math.min(vw-60,parseFloat(s.left)));
        T=Math.max(6,Math.min(vh-60,parseFloat(s.top)));
      }
    }catch(_){}
    root.style.left=L+'px';root.style.top=T+'px';
  }
  function anchor(){
    const vw=P.innerWidth||380,vh=P.innerHeight||680;
    const ow=orb.offsetWidth||54,oh=orb.offsetHeight||54;
    const ww=Math.min(win.offsetWidth||470,vw-16);
    const wh=Math.min(win.offsetHeight||770,vh-96);
    const gap=10,pad=8;
    let left,top;
    if(L+ow/2>vw/2){left=Math.max(pad,vw-ww-pad)}
    else{left=Math.min(Math.max(pad,L),Math.max(pad,vw-ww-pad))}
    if(T+oh/2>vh/2){
      top=T-wh-gap;
      if(top<pad)top=pad;
    }else{
      top=T+oh+gap;
      if(top+wh>vh-pad)top=Math.max(pad,vh-wh-pad);
    }
    win.style.left=left+'px';
    win.style.top=top+'px';
    win.style.right='auto';
    win.style.bottom='auto';
  }
  function down(e){drag=true;moved=false;pid=e.pointerId;sx=e.clientX;sy=e.clientY;bL=parseFloat(root.style.left)||0;bT=parseFloat(root.style.top)||0}
  orb.addEventListener('pointerdown',e=>{e.preventDefault();e.stopPropagation();down(e);try{orb.setPointerCapture(e.pointerId)}catch(_){}});
  hd.addEventListener('pointerdown',e=>{if(e.target.closest('button,select,input'))return;e.preventDefault();e.stopPropagation();down(e);try{hd.setPointerCapture(e.pointerId)}catch(_){}});
  D.addEventListener('pointermove',e=>{
    if(!drag||e.pointerId!==pid)return;
    e.preventDefault();
    const dx=e.clientX-sx,dy=e.clientY-sy;
    if(Math.abs(dx)+Math.abs(dy)>5)moved=true;
    const vw=P.innerWidth||380,vh=P.innerHeight||680;
    L=Math.max(6,Math.min(vw-60,bL+dx));T=Math.max(6,Math.min(vh-60,bT+dy));
    root.style.left=L+'px';root.style.top=T+'px';anchor();
  },{passive:false,signal:AC.signal});
  try{P.addEventListener('resize',()=>{try{anchor()}catch(_){}},{signal:AC.signal})}catch(_){}
  D.addEventListener('pointerup',e=>{
    if(!drag||e.pointerId!==pid)return;
    const isOrb=e.target===orb||orb.contains(e.target);
    drag=false;pid=null;
    try{localStorage.setItem(POS_KEY,JSON.stringify({left:L,top:T}))}catch(_){}
    anchor();
    if(isOrb&&!moved){win.hidden=!win.hidden;syncOrbOpen();if(!win.hidden){anchor();if(!items.length)loadBook().catch(()=>{})}}
  },{signal:AC.signal});
  D.addEventListener('pointercancel',e=>{if(e.pointerId!==pid)return;drag=false;pid=null},{signal:AC.signal});

  /* ===== Dọn dẹp ===== */
  const disposers=[];
  function bindChat(){
    const on=apiFn('eventOn');
    let TE=null;
    try{if(typeof tavern_events!=='undefined')TE=tavern_events}catch(_){}
    if(!TE){try{TE=P.tavern_events}catch(_){}}
    if(!on||!TE)return;
    const bind=(n,fn)=>{if(!n)return;try{const h=on(n,fn);if(h&&typeof h.stop==='function')disposers.push(h.stop)}catch(_){}};
    const reload=()=>{try{loadDb();tgtLists=null;userLists=null;recLists=null;switchPage(page)}catch(e){console.error(e)}};
    bind(TE.CHAT_CHANGED||'chat_id_changed',reload);
    bind(TE.CHAT_CREATED||'chat_created',reload);
  }
  const cleanup=()=>{
    if(cleanup.done)return;
    cleanup.done=true;AC.abort();
    disposers.splice(0).forEach(s=>{try{s()}catch(_){}});
    root.remove();style.remove();
  };
  cleanup.done=false;
  P.__TH_YINJIAO_CLEANUP__=cleanup;
  window.addEventListener('pagehide',cleanup,{once:true});
  window.addEventListener('beforeunload',cleanup,{once:true});
  if(FRAME){
    try{
      const obs=new MutationObserver(()=>{if(!FRAME.isConnected)cleanup()});
      obs.observe(D.documentElement,{childList:true,subtree:true});
      AC.signal.addEventListener('abort',()=>obs.disconnect(),{once:true});
    }catch(_){}
  }

  /* ===== Biểu tượng ngôi sao ===== */
  (function(){
    const p=root.querySelector('.sp');if(!p)return;
    const N=12,R=49,r=19,cx=50,cy=50,pts=[];
    for(let i=0;i<N*2;i++){
      const rad=(i%2===0)?R:r,a=(Math.PI/N)*i-Math.PI/2;
      pts.push((cx+rad*Math.cos(a)).toFixed(2)+','+(cy+rad*Math.sin(a)).toFixed(2));
    }
    p.setAttribute('d','M'+pts.join(' L')+' Z');
  })();

  STAGE.set('Giai đoạn 5 · Bắt đầu gắn kết');
  /* ===== Khởi động ===== */
  (function boot(){
    try{
      const host=D||document;
      const mount=host.body||host.documentElement||document.body||document.documentElement;
      try{(host.head||host.documentElement||document.head).appendChild(style)}catch(_){try{document.head.appendChild(style)}catch(_2){}}
      if(mount&&mount.appendChild)mount.appendChild(root);
      STAGE.set(root.isConnected?'Giai đoạn 6 · Đã gắn':'Giai đoạn 6 · Gắn kết chưa hiệu lực');
    }catch(_){}
    // Kiểm tra gắn kết：500ms Nếu sau đó vẫn chưa kết nối được thì đổi vật chủ rồi thử lại
    setTimeout(()=>{
      try{
        if(root.isConnected)return;
        const alt=(document.body||document.documentElement);
        if(alt&&alt.appendChild)alt.appendChild(root);
        if(!root.isConnected&&window.top&&window.top!==window){
          const t=window.top.document;
          if(t&&(t.body||t.documentElement))(t.body||t.documentElement).appendChild(root);
        }
      }catch(_){}
    },500);
    try{
      const rem=new MutationObserver(()=>{if(!root.isConnected)(D.body||D.documentElement)?.append(root)});
      rem.observe(D.documentElement,{childList:true,subtree:true});
      AC.signal.addEventListener('abort',()=>rem.disconnect(),{once:true});
    }catch(_){}
    const steps=[
      ['applyUi',applyUi],['loadDb',loadDb],['applyAutoSyncUi',applyAutoSyncUi],
      ['renderCats',renderCats],['buildWsTypes',buildWsTypes],['renderWsForm',renderWsForm],
      ['fillApi',fillApi],['switchPage',()=>switchPage('goods')],
      ['renderTList',renderTList],['renderTDetail',renderTDetail],['renderUDetail',renderUDetail],
      ['renderRecords',renderRecords],['fillPools',fillPools],['loadScopes',loadScopes],
      ['loadWsDraft',loadWsDraft],['loadRwDraft',loadRwDraft],
      ['renderWsRes',renderWsRes],['renderRwRes',renderRwRes],
      ['renderTagPool',renderTagPool],['renderGbTagPool',renderGbTagPool],['renderGcTagPool',renderGcTagPool],
      ['renderRwTagPool',renderRwTagPool],['renderGgTagPool',renderGgTagPool],['renderGlTagPool',renderGlTagPool],['dvInit',dvInit],['renderDvPick',renderDvPick],
      ['syncRarityHint',syncRarityHint],
      ['initPos',initPos],['anchor',anchor],
      ['bindChat',bindChat],['bindAutoSync',bindAutoSync]
    ];
    const failed=[];
    steps.forEach(([name,fn])=>{
      try{fn()}catch(e){failed.push(name);try{console.error('[X] '+name,e)}catch(_){}}
    });
    try{
      setSt(failed.length
        ? ('Terminal đã sẵn sàng, nhưng có '+failed.length+' mục chưa khởi động được：'+failed.join('、'))
        : ('Thiết bị đầu cuối sẵn sàng · Mức hiện tại '+(db.chatId||chatId())));
    }catch(_){}
    if(failed.length)STAGE.fail('Giai đoạn 7 · Mô-đun lỗi：'+failed.join('、'));
    else STAGE.done();
  })();

  } catch (e) {
    try {
      let doc=document;
      try{if(window.parent&&window.parent.document)doc=window.parent.document}catch(_){}
      const box=doc.createElement('div');
      box.textContent='⚠ Khởi tạo thiết bị đầu cuối Mạng lưới dâm khiếu thất bại：'+((e&&e.message)||e);
      box.style.cssText='position:fixed;left:8px;bottom:8px;z-index:2147483647;background:#b91c1c;color:#fff;font:12px/1.5 ui-monospace,monospace;padding:8px 10px;border-radius:4px;max-width:82vw;box-shadow:0 4px 14px rgba(0,0,0,.5)';
      (doc.body||doc.documentElement).appendChild(box);
    } catch (_) {}
    try{console.error('[X] Khởi tạo thất bại',e)}catch(_){}
  }
})();
